INSERT INTO public.books (id, description, file_path, title) VALUES (1, 'Трогательная и остроумная история о девочке, выросшей в армянской деревне, где каждый день — маленькое приключение, а любовь к жизни и людям сильнее любых трудностей. Автор — Наринэ Абгарян — рисует мир, полный тепла, юмора и наивной мудрости.', '/Абгарян. Зулали.fb2', 'Зулали');
INSERT INTO public.books (id, description, file_path, title) VALUES (2, 'Ироничная, местами грустная, но всегда живая повесть о женщине, которая, сбежав от московской суеты, находит себя в провинциальной Армении. Через столкновение культур, бытовые курьезы и неожиданные дружбы раскрывается тема поиска дома и внутренней гармонии.', '/Абгарян. Понаехавшая.fb2', 'Понаехавшая');
INSERT INTO public.books (id, description, file_path, title) VALUES (3, 'Сборник рассказов, где магический реализм переплетается с бытовой прозой. Каждая история — как яблоко с неба: неожиданная, сочная, сладкая или кислая, но всегда несущая в себе зерно истины о любви, судьбе и человеческой природе.', '/Абгарян. С неба упали три яблока.fb2', 'С неба упали три яблока');
INSERT INTO public.books (id, description, file_path, title) VALUES (4, 'Философская проза Кобо Абэ — это путешествие вглубь человеческого сознания, где реальность тает, как лед, а личность растворяется в абсурде. Книга о страхе, одиночестве и попытке найти смысл в мире, где климат меняется не только снаружи, но и внутри.', '/Абэ. Четвертый ледниковый период.fb2', 'Четвертый ледниковый период');
INSERT INTO public.books (id, description, file_path, title) VALUES (5, 'Исторический детектив Акунина, действие которого происходит в провинциальной России конца XIX века. Молодая монахиня Пелагия расследует загадочное исчезновение церковного бульдога, раскрывая заодно темные тайны местного общества.', '/Акунин. Пелагия и белый бульдог.fb2', 'Пелагия и белый бульдог');
INSERT INTO public.books (id, description, file_path, title) VALUES (6, 'Классика японской литературы, где через несколько противоречивых свидетельств одного и того же убийства раскрывается суть человеческой природы: каждый видит правду по-своему, и объективности не существует.', '/Акутагава. Ворота Расёмон.fb2', 'Ворота Расёмон');
INSERT INTO public.books (id, description, file_path, title) VALUES (7, 'Фантастический эпос, где древние мифы сталкиваются с космическими технологиями. Герой, избранный судьбой, должен найти легендарные сокровища Валькирии, чтобы спасти галактику от гибели — и понять, что истинное сокровище — внутри него самого.', '/Алексеев. Сокровища Валькирии. Стоящий у Солнца.fb2', 'Сокровища Валькирии. Стоящий у Солнца');
INSERT INTO public.books (id, description, file_path, title) VALUES (8, 'Мощная социальная сага Жоржи Амаду о борьбе бедняков Бразилии против угнетения. Через судьбы шахтеров, детей и повстанцев автор показывает, как любовь, музыка и вера становятся оружием против несправедливости.', '/Амаду. Генералы песчаных карьеров.fb2', 'Генералы песчаных карьеров');
INSERT INTO public.books (id, description, file_path, title) VALUES (9, 'Фундаментальный труд Аристотеля, заложивший основы западной философии. Книга исследует природу бытия, сущности, причинности и первопричин. Это не просто философия — это карта реальности, написанная 2300 лет назад и актуальная до сих пор.', '/Аристотель. Метафизика.fb2', 'Метафизика');
INSERT INTO public.books (id, description, file_path, title) VALUES (10, 'Аристотель анализирует устройство государств, формы правления и природу гражданского общества. Книга, которая легла в основу политической науки: от нее ведут начало идеи демократии, справедливости и общего блага.', '/Аристотель. Политика.fb2', 'Политика');
INSERT INTO public.books (id, description, file_path, title) VALUES (11, 'Философский труд, где Спиноза исследует природу Бога, человека и свободы. Автор показывает, что все есть единая субстанция — и что свобода — это понимание необходимости. Книга, изменившая философию.', '/Спиноза. Этика.fb2', 'Этика');
INSERT INTO public.books (id, description, file_path, title) VALUES (12, 'Сборник пьес Аристофана и его современников — острейшая сатира на политиков, философов и обычаи Древней Греции. Здесь боги спорят с людьми, женщины захватывают власть, а мир спасается с помощью… пениса. Юмор, который актуален спустя тысячелетия.', '/Аристофан и др. Античная комедия.fb2', 'Античная комедия');
INSERT INTO public.books (id, description, file_path, title) VALUES (13, 'Роман о четырех женщинах, которые сбегают от серой английской жизни в итальянский замок. Под южным солнцем они заново открывают для себя любовь, красоту и смысл жизни. История о том, как весна может начаться в душе — даже если за окном дождь.', '/Арним. Чарующий апрель.fb2', 'Чарующий апрель');
INSERT INTO public.books (id, description, file_path, title) VALUES (14, 'Аллегорическая повесть о человеке, который пытается поймать легендарную рыбу — и встречает самого себя. Через природу, реку и рыбу Астафьев говорит о совести, грехе, искуплении и связи человека с миром. Проза, пропитанная болью и любовью к родной земле.', '/Астафьев. Царь-рыба.fb2', 'Царь-рыба');
INSERT INTO public.books (id, description, file_path, title) VALUES (109, 'Философский роман о будущем, где интеллектуалы играют в игру, заменяющую реальность. Гессе исследует, что важнее — знание или жизнь? Книга, написанная с мудростью и печалью.', '/Гессе. Игра в бисер.fb2', 'Игра в бисер');
INSERT INTO public.books (id, description, file_path, title) VALUES (15, 'Сборник стихов Анны Ахматовой — лирический дневник эпохи. От любовной нежности до трагедии репрессий, от личного горя до всенародного страдания. Каждое стихотворение — как капля ртути: тяжелое, блестящее, ядовитое и неизбежное.', '/Ахматова. Бег времени.fb2', 'Бег времени');
INSERT INTO public.books (id, description, file_path, title) VALUES (16, 'Роман-пазл, где одна семья переживает немецкую историю XX века. Через воспоминания, документы и внутренние монологи Бёлль показывает, как фашизм, война и послевоенное время ломают судьбы, но не убивают человечность.', '/Бёлль. Бильярд в половине десятого.fb2', 'Бильярд в половине десятого');
INSERT INTO public.books (id, description, file_path, title) VALUES (17, 'Классика анархистской мысли. Бакунин отвергает государство как инструмент угнетения и призывает к свободному объединению людей на основе самоуправления. Книга-взрыв, которая до сих пор вдохновляет бунтарей и революционеров.', '/Бакунин. Государственность и анархия.fb2', 'Государственность и анархия');
INSERT INTO public.books (id, description, file_path, title) VALUES (18, 'Антиутопия о небоскребе, который становится микрокосмом общества. По мере роста здания растет и агрессия жильцов. Баллард показывает, как архитектура формирует поведение, а цивилизация — тонкая пленка над хаосом.', '/Баллард. Высотка.fb2', 'Высотка');
INSERT INTO public.books (id, description, file_path, title) VALUES (19, 'Путешествие по США глазами британца, который видит не страну свободы, а пустыню потребления. Баллард исследует культурный коллапс, где реклама, телевидение и автомобильные дороги заменяют реальность.', '/Баллард. Привет, Америка!.fb2', 'Привет, Америка!');
INSERT INTO public.books (id, description, file_path, title) VALUES (20, 'Хайку мастера Басё — капли дзен в океане бытия. Каждое стихотворение — мгновение просветления: луна, лягушка, ветер, снег… Простота, за которой скрывается бездна смысла.', '/Басё. Во тьме безлунной ночи.fb2', 'Во тьме безлунной ночи');
INSERT INTO public.books (id, description, file_path, title) VALUES (21, 'Роман о поэте, который пытается примирить гений и безумие, искусство и деньги, любовь и одиночество. Беллоу создает портрет Америки через призму двух поэтов — одного живого, другого мертвого, но оба — потерянные в мире, который их не понимает.', '/Беллоу. Подарок от Гумбольдта.fb2', 'Подарок от Гумбольдта');
INSERT INTO public.books (id, description, file_path, title) VALUES (22, 'Научно-фантастическая повесть о человеке, который научился летать с помощью искусственных крыльев. Но свобода обернулась проклятием: общество не готово принять того, кто выше его. Беляев предвосхитил темы трансгуманизма и социальной изоляции гения.', '/Беляев. Ариэль.fb2', 'Ариэль');
INSERT INTO public.books (id, description, file_path, title) VALUES (23, 'Утопия-антиутопия: ученый создает устройство, способное управлять человечеством. Но абсолютная власть требует абсолютной жестокости. Беляев задает вопрос: можно ли спасти мир, уничтожив свободу?', '/Беляев. Властелин мира.fb2', 'Властелин мира');
INSERT INTO public.books (id, description, file_path, title) VALUES (24, 'Ужасающая история о голове, которая продолжает жить после смерти тела. Эксперимент, который обнажает аморальность науки без совести. Один из первых романов о биоэтике — и один из самых жутких.', '/Беляев. Голова профессора Доуэля.fb2', 'Голова профессора Доуэля');
INSERT INTO public.books (id, description, file_path, title) VALUES (25, 'Сатирическая фантастика: в будущем воздух стал товаром. Беляев предсказал экологический кризис и капитализм, доведенный до абсурда. История, которая сегодня звучит как пророчество.', '/Беляев. Продавец воздуха.fb2', 'Продавец воздуха');
INSERT INTO public.books (id, description, file_path, title) VALUES (26, 'Две повести о трансплантации лица — задолго до того, как это стало возможным в реальности. Беляев исследует, что делает человека человеком: тело, память, душа? И можно ли вернуть себе лицо — и себя?', '/Беляев. Человек, потерявший лицо. Человек, нашедший свое лицо.fb2', 'Человек, потерявший лицо. Человек, нашедший свое лицо');
INSERT INTO public.books (id, description, file_path, title) VALUES (27, 'Классика советской фантастики: мальчик, выросший под водой, пытается найти место в мире людей. История о любви, предательстве и невозможности быть одновременно двумя существами. Образ Ихтиандра стал символом отчуждения.', '/Беляев. Человек-амфибия.fb2', 'Человек-амфибия');
INSERT INTO public.books (id, description, file_path, title) VALUES (28, 'Антиутопия о насилии, свободе воли и государственном контроле. Подросток-преступник проходит "исправление" — и теряет способность выбирать зло. Берджесс спрашивает: лучше ли человек без зла, если он не человек?', '/Берджесс. Заводной апельсин.fb2', 'Заводной апельсин');
INSERT INTO public.books (id, description, file_path, title) VALUES (29, 'Комедийная сага о поэте, который ненавидит мир, но не может без него жить. Берджесс играет с языком, формой и читательскими ожиданиями, создавая героя, который одновременно гений и неудачник.', '/Берджесс. Мистер Эндерби. Взгляд изнутри.fb2', 'Мистер Эндерби. Взгляд изнутри');
INSERT INTO public.books (id, description, file_path, title) VALUES (30, 'Роман о сексуальности, власти и творчестве. Берджесс исследует, как желание формирует личность — и как легко оно может превратиться в разрушение. Книга, написанная с дерзостью и интеллектуальной страстью.', '/Берджесс. Семя желания (2022).fb2', 'Семя желания (2022)');
INSERT INTO public.books (id, description, file_path, title) VALUES (31, 'Философский труд о природе искусства, свободы и божественного в человеке. Бердяев видит творчество как акт преодоления хаоса и путь к духовному освобождению. Книга для тех, кто верит, что искусство — это не развлечение, а спасение.', '/Бердяев. Смысл творчества.fb2', 'Смысл творчества');
INSERT INTO public.books (id, description, file_path, title) VALUES (32, 'Нон-фикшн детектив, основанный на реальных событиях в Саванне. Убийство, аристократы, ведьмы, суд — и все это на фоне южного шарма. Берендт создает портрет города, где добро и зло танцуют под одну музыку.', '/Берендт. Полночь в саду добра и зла.fb2', 'Полночь в саду добра и зла');
INSERT INTO public.books (id, description, file_path, title) VALUES (33, 'Любовная история на фоне Второй мировой войны. Итальянский офицер и греческая девушка находят любовь там, где ее быть не должно. Берньер пишет о войне, которая разрушает все — кроме человеческого сердца.', '/Берньер. Мандолина капитана Корелли.fb2', 'Мандолина капитана Корелли');
INSERT INTO public.books (id, description, file_path, title) VALUES (34, 'Манифест историка: Блок утверждает, что история — это не хроника событий, а диалог между прошлым и настоящим. Книга учит задавать вопросы мертвым — и слушать их ответы.', '/Блок Марк. Апология истории.fb2', 'Апология истории');
INSERT INTO public.books (id, description, file_path, title) VALUES (35, 'Поэтический сборник Александра Блока — музыка русской души в эпоху перемен. От символизма до революционного пафоса, от любви до отчаяния. Стихи, которые звучат как пророчество и как эпитафия.', '/Блок. Покой нам только снится....fb2', 'Покой нам только снится...');
INSERT INTO public.books (id, description, file_path, title) VALUES (36, 'Роман о любви, которая не может существовать в реальном мире. Болдуин исследует расовые, сексуальные и социальные границы через историю гея в Париже 1950-х. Книга о том, как общество убивает любовь — и как любовь выживает вопреки всему.', '/Болдуин. Комната Джованни.fb2', 'Комната Джованни');
INSERT INTO public.books (id, description, file_path, title) VALUES (37, 'Поэтический сборник Ольги Борисовой — лирика о времени, природе и внутреннем мире. Каждое стихотворение — как смена сезона: нежное, меланхоличное, пронзительное. Книга для тех, кто слышит музыку в тишине.', '/Борисова. Vremena goda.fb2', 'Vremena goda');
INSERT INTO public.books (id, description, file_path, title) VALUES (38, 'Борхес играет с реальностью, как шахматист с фигурами. Лабиринты, зеркала, бесконечные библиотеки — все это метафоры познания. Каждый рассказ — философская загадка, которую нельзя решить, но можно прожить.', '/Борхес. Новые расследования (сборник).fb2', 'Новые расследования (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (39, 'Популярная наука в лучшем виде: от Большого взрыва до появления человека — с юмором, удивлением и благоговением. Брайсон делает сложное простым, а скучное — увлекательным. Книга, после которой мир кажется чудом.', '/Брайсон. Краткая история почти всего на свете.fb2', 'Краткая история почти всего на свете');
INSERT INTO public.books (id, description, file_path, title) VALUES (40, 'Киберпанк до киберпанка: мир перенаселения, медиа-хаоса и социального распада. Браннер предсказал интернет, мемы и кризис идентичности. Роман, который читается как пророчество — и как предупреждение.', '/Браннер. Всем стоять на Занзибаре.fb2', 'Всем стоять на Занзибаре');
INSERT INTO public.books (id, description, file_path, title) VALUES (41, 'Триллер, взорвавший мир: убийство в Лувре, загадки Леонардо, тайны христианства. Браун создает интеллектуальную игру, где каждый символ — ключ, а каждая картина — код. Книга, которая заставила миллионы перечитывать историю.', '/Браун. Код да Винчи.fb2', 'Код да Винчи');
INSERT INTO public.books (id, description, file_path, title) VALUES (42, 'Сиквел "Кода да Винчи": на этот раз действие в Вашингтоне, а загадки — масонские. Браун исследует эзотерику, науку и веру, задавая вопрос: что делает нас человечными — разум или дух?', '/Браун. Утраченный символ.fb2', 'Утраченный символ');
INSERT INTO public.books (id, description, file_path, title) VALUES (43, 'Готический роман о страсти, мести и проклятии. Любовь Кэтрин и Хитклифа — как ураган: разрушительная, всепоглощающая, вечная. Бронте создала историю, которая не стареет — потому что любовь и боль не имеют срока годности.', '/Бронте. Грозовой перевал.fb2', 'Грозовой перевал');
INSERT INTO public.books (id, description, file_path, title) VALUES (44, 'Роман-скандал: женщина уходит от мужа-алкоголика, чтобы защитить сына. Бронте бросает вызов викторианской морали и создает героиню, которая выбирает свободу, а не покорность. Одна из первых феминистских книг в истории литературы.', '/Бронте. Незнакомка из Уайлдфелл-Холла.fb2', 'Незнакомка из Уайлдфелл-Холла');
INSERT INTO public.books (id, description, file_path, title) VALUES (45, 'История любви учительницы и молодого аристократа — нежная, меланхоличная, обреченная. Бронте исследует классовые барьеры, внутреннюю силу женщины и цену независимости. Роман, написанный с тонкостью и глубоким психологизмом.', '/Бронте. Учитель.fb2', 'Учитель');
INSERT INTO public.books (id, description, file_path, title) VALUES (46, 'Социальный роман о промышленной революции, классовой борьбе и женской дружбе. Бронте показывает, как личные судьбы переплетаются с историей — и как женщины находят силы менять мир, даже когда он против них.', '/Бронте. Шерли.fb2', 'Шерли');
INSERT INTO public.books (id, description, file_path, title) VALUES (47, 'Исторический детектив, действие которого происходит в Древней Руси. Тайны, заговоры, язычество и христианство — все это на фоне эпической борьбы за власть. Брусникин создает мир, где каждый символ — ключ, а каждая икона — загадка.', '/Брусникин. Девятный Спас.fb2', 'Девятный Спас');
INSERT INTO public.books (id, description, file_path, title) VALUES (48, 'Сатира Булгакова, где бюрократия превращается в ад, а наука — в катастрофу. "Роковые яйца" — о том, как хорошие идеи рождают чудовищ. "Дьяволиада" — о том, как чиновник сходит с ума в системе, которая сама безумна.', '/Булгаков. Дьяволиада. Роковые яйца (сборник).fb2', 'Дьяволиада. Роковые яйца (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (49, 'Вечный роман: дьявол приходит в Москву, чтобы устроить бал, а влюбленные пытаются спастись от реальности. Булгаков смешивает сатиру, философию, любовь и мистику. Книга, которая читается по-новому в каждом возрасте.', '/Булгаков. Мастер и Маргарита.fb2', 'Мастер и Маргарита');
INSERT INTO public.books (id, description, file_path, title) VALUES (50, 'Повесть о зависимости, написанная с хирургической точностью. Булгаков, бывший врач, показывает, как морфий разрушает личность — и как трудно признать свою слабость. История, основанная на личном опыте, — без прикрас и оправданий.', '/Булгаков. Морфий.fb2', 'Морфий');
INSERT INTO public.books (id, description, file_path, title) VALUES (51, 'Две повести о войне, совести и предательстве. Быков показывает, как в экстремальных условиях проявляется суть человека: кто сломается, кто предаст, а кто останется человеком. Проза, пропитанная болью и правдой.', '/Быков. Сотников. Обелиск (сборник).fb2', 'Сотников. Обелиск (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (52, 'Мрачный фэнтези-триллер: убийца охотится за детьми, а город погружается в панику. Бэнкс создает атмосферу неотвратимого зла — и показывает, как хрупка граница между цивилизацией и хаосом.', '/Бэнкс. Воронья дорога.fb2', 'Воронья дорога');
INSERT INTO public.books (id, description, file_path, title) VALUES (53, 'Психологический триллер о человеке, который теряет память — и находит себя в мире, где все хотят его убить. Бэнкс играет с идентичностью, реальностью и страхом. Книга, которая держит в напряжении до последней страницы.', '/Бэнкс. Осиная фабрика.fb2', 'Осиная фабрика');
INSERT INTO public.books (id, description, file_path, title) VALUES (54, 'Социальный роман о жизни на дне общества. Бэнкс показывает, как бедность, насилие и отчаяние ломают людей — и как иногда в этом аду рождается надежда. Проза без прикрас, но с состраданием.', '/Бэнкс. Улица отчаяния.fb2', 'Улица отчаяния');
INSERT INTO public.books (id, description, file_path, title) VALUES (55, 'Триллер о маньяке, который оставляет за собой кровавый след. Бэнкс исследует природу зла, полицейскую работу и психологию жертв. Книга, которая заставляет задуматься: кто страшнее — убийца или общество, его породившее?', '/Бэнкс. Шаги по стеклу.fb2', 'Шаги по стеклу');
INSERT INTO public.books (id, description, file_path, title) VALUES (56, 'Научно-популярная книга о рождении Вселенной. Вайнберг объясняет, как из бесконечно горячей точки возникло все, что мы знаем. Книга для тех, кто хочет понять, откуда мы пришли — и куда движемся.', '/Вайнберг. Первые три минуты.fb2', 'Первые три минуты');
INSERT INTO public.books (id, description, file_path, title) VALUES (57, 'Биография легендарного анархистского атамана. Веллер исследует личность, которая стала символом свободы и хаоса. Книга о человеке, который хотел освободить крестьян — и стал жертвой собственной мечты.', '/Веллер. Махно.fb2', 'Махно');
INSERT INTO public.books (id, description, file_path, title) VALUES (58, 'Полуавтобиографический роман о врачебной практике в российской провинции. Вересаев показывает, как болезнь и страдание обнажают суть человека — и как врач учится быть человеком среди боли.', '/Вересаев. Записки врача.fb2', 'Записки врача');
INSERT INTO public.books (id, description, file_path, title) VALUES (59, 'Фантастика, предвосхитившая интернет и виртуальную реальность. Виндж создает мир, где хакеры — волшебники, а киберпространство — новая вселенная. Книга, которая вдохновила создателей "Матрицы".', '/Виндж. «Подлинные имена» и выход за пределы киберпространства.fb2', '«Подлинные имена» и выход за пределы киберпространства');
INSERT INTO public.books (id, description, file_path, title) VALUES (60, 'Эссе о моменте, когда искусственный интеллект превзойдет человеческий разум. Виндж предсказывает будущее, где технологии меняют саму природу человечества. Книга-предупреждение и книга-мечта.', '/Виндж. Сингулярность.fb2', 'Сингулярность');
INSERT INTO public.books (id, description, file_path, title) VALUES (61, 'Философская проза о науке, этике и будущем. Винер, отец кибернетики, размышляет о том, как технологии меняют общество — и кто несет за это ответственность. Книга для тех, кто верит, что наука должна служить человеку.', '/Винер. Корпорация «Бог и голем».fb2', 'Корпорация «Бог и голем»');
INSERT INTO public.books (id, description, file_path, title) VALUES (62, 'Гениальная и загадочная книга: Витгенштейн пытается определить границы языка и мышления. "О чем нельзя говорить, о том следует молчать". Трактат, который изменил философию — и оставил больше вопросов, чем ответов.', '/Витгенштейн. Логико-философский трактат.fb2', 'Логико-философский трактат');
INSERT INTO public.books (id, description, file_path, title) VALUES (63, 'Современная драма о любви, деньгах и предательстве. Вишневский показывает, как амбиции разрушают отношения — и как сложно остаться человеком в мире, где все имеет цену. Книга о том, что настоящий "гранд" — не отель, а душа.', '/Вишневский. Гранд.fb2', 'Гранд');
INSERT INTO public.books (id, description, file_path, title) VALUES (64, 'Любовная история в эпоху интернета. Два человека находят друг друга онлайн — и теряют в реальности. Вишневский исследует, как технологии меняют любовь: делают ее ближе — и дальше одновременно.', '/Вишневский. Одиночество в Сети.fb2', 'Одиночество в Сети');
INSERT INTO public.books (id, description, file_path, title) VALUES (65, 'Элегия о потерянном рае: аристократический дом, юность, любовь, вера. Во создает портрет Англии, которая исчезла — и чувств, которые остались. Книга, написанная с ностальгией и изысканной грустью.', '/Во. Возвращение в Брайдсхед.fb2', 'Возвращение в Брайдсхед');
INSERT INTO public.books (id, description, file_path, title) VALUES (66, 'Сатира на военную бюрократию и абсурд войны. Вторая часть "Словесной атаки" — еще более циничная, еще более смешная, еще более горькая. Во показывает, как глупость убивает умнее, чем пули.', '/Во. И побольше флагов.fb2', 'И побольше флагов');
INSERT INTO public.books (id, description, file_path, title) VALUES (67, 'Роман о любви, которая длится всю жизнь — даже когда любить уже некого. Во исследует память, старость и неизбежность утраты. Книга, написанная с тонкостью и глубоким уважением к человеческому сердцу.', '/Во. Незабвенная.fb2', 'Незабвенная');
INSERT INTO public.books (id, description, file_path, title) VALUES (68, 'Антиутопия о войне, времени и человеческой глупости. Воннегут, участник бомбардировки Дрездена, создает историю, где герой путешествует во времени — и не может спастись от абсурда. "Так бывает" — главная фраза книги.', '/Воннегут. Бойня № 5.fb2', 'Бойня № 5');
INSERT INTO public.books (id, description, file_path, title) VALUES (69, 'Фантастика о путешествиях во времени, где каждое изменение прошлого разрушает будущее. Воннегут играет с причинностью, моралью и свободой воли. Книга, которая заставляет задуматься: а если бы можно было все исправить?', '/Воннегут. Времетрясение.fb2', 'Времетрясение');
INSERT INTO public.books (id, description, file_path, title) VALUES (70, 'Роман-апокалипсис: через миллион лет люди превращаются в морских котиков. Воннегут саркастически исследует эволюцию, природу человека и смысл жизни. Книга, написанная с юмором и отчаянием.', '/Воннегут. Галапагосы.fb2', 'Галапагосы');
INSERT INTO public.books (id, description, file_path, title) VALUES (71, 'Сатира о богатстве, безумии и гуманизме. Миллиардер тратит состояние на помощь бедным — и его объявляют сумасшедшим. Воннегут спрашивает: кто на самом деле безумен — тот, кто помогает, или тот, кто считает это безумием?', '/Воннегут. Дай Вам Бог здоровья, мистер Розуотер.fb2', 'Дай Вам Бог здоровья, мистер Розуотер');
INSERT INTO public.books (id, description, file_path, title) VALUES (72, 'Черный юмор, абсурд и философия. Воннегут сталкивает двух героев — одного доброго, другого злого — и показывает, как мир разрушает обоих. Книга, написанная с отчаянием и надеждой одновременно.', '/Воннегут. Завтрак для чемпионов.fb2', 'Завтрак для чемпионов');
INSERT INTO public.books (id, description, file_path, title) VALUES (73, 'Научная фантастика о религии, науке и власти. Ученый изобретает устройство, которое позволяет видеть будущее — и становится мессией. Воннегут исследует, как легко превратить науку в религию — и как трудно остаться человеком.', '/Воннегут. Колыбель для кошки.fb2', 'Колыбель для кошки');
INSERT INTO public.books (id, description, file_path, title) VALUES (74, 'Роман о войне, написанный с горьким юмором. Воннегут показывает, как солдаты выживают в аду — и как трудно вернуться в мир, который не понимает их боли. Книга о том, что героизм — это не подвиг, а выживание.', '/Воннегут. Малый Не Промах.fb2', 'Малый Не Промах');
INSERT INTO public.books (id, description, file_path, title) VALUES (75, 'История о писателе, который становится нацистом — и пытается искупить вину. Воннегут исследует природу зла, совести и ответственности. Книга, написанная с болью и без иллюзий.', '/Воннегут. Матерь Тьма.fb2', 'Матерь Тьма');
INSERT INTO public.books (id, description, file_path, title) VALUES (76, 'Роман о миллионере, который женится на молодых женщинах — и убивает их. Воннегут создает аллегорию капитализма, где деньги заменяют мораль. Книга, написанная с сарказмом и гневом.', '/Воннегут. Синяя борода.fb2', 'Синяя борода');
INSERT INTO public.books (id, description, file_path, title) VALUES (77, 'Фантастика о смысле жизни, свободе воли и инопланетянах. Воннегут показывает, что вся история человечества — случайность, управляемая высшими силами. Книга, которая заставляет смеяться — и плакать от бессмысленности.', '/Воннегут. Сирены Титана.fb2', 'Сирены Титана');
INSERT INTO public.books (id, description, file_path, title) VALUES (78, 'Сатира на американское общество, где магия — это бизнес, а религия — шоу. Воннегут исследует, как легко превратить чудо в товар — и как трудно сохранить веру в мире, где все продается.', '/Воннегут. Фокус-покус.fb2', 'Фокус-покус');
INSERT INTO public.books (id, description, file_path, title) VALUES (79, 'Комедия о свадьбах, невестах и аристократических глупостях. Вудхаус создает мир, где проблемы решаются за чаем, а любовь побеждает благодаря случайности. Книга, написанная с легкостью и британским юмором.', '/Вудхаус. Брачный сезон.fb2', 'Брачный сезон');
INSERT INTO public.books (id, description, file_path, title) VALUES (80, 'Юмористическая повесть о джентльмене Берти Вустере и его гениальном лакее Дживсе. Каждая история — как шахматная партия, где Дживс всегда на шаг впереди. Вудхаус — мастер комедии положений.', '/Вудхаус. Ваша взяла, Дживс!.fb2', 'Ваша взяла, Дживс!');
INSERT INTO public.books (id, description, file_path, title) VALUES (81, 'Еще одна история о Берти и Дживсе, где аристократические замки, тетушки и помолвки создают идеальный хаос. Вудхаус показывает, что настоящая верность — не перед хозяином, а перед здравым смыслом.', '/Вудхаус. Дживс и феодальная верность.fb2', 'Дживс и феодальная верность');
INSERT INTO public.books (id, description, file_path, title) VALUES (82, 'Сборник рассказов, где Дживс спасает Берти от очередных неприятностей — будь то помолвка, тетка или кража статуэтки. Вудхаус — король английского юмора, где даже катастрофа заканчивается чаем и смеянием.', '/Вудхаус. Дживс, вы – гений!.fb2', 'Дживс, вы – гений!');
INSERT INTO public.books (id, description, file_path, title) VALUES (83, 'Юмористические рассказы о чудаковатой семье Муллинеров. Каждый член семьи — уникален, каждый случай — абсурден. Вудхаус создает галерею персонажей, которые вызывают улыбку даже в самый хмурый день.', '/Вудхаус. Знакомьтесь мистер Муллинер.fb2', 'Знакомьтесь мистер Муллинер');
INSERT INTO public.books (id, description, file_path, title) VALUES (84, 'Еще одна книга о неразлучной паре: глуповатый аристократ и его сверхразумный лакей. Вудхаус показывает, что истинный джентльмен — это не титул, а умение признать, что Дживс всегда прав.', '/Вудхаус. Посоветуйтесь с Дживсом.fb2', 'Посоветуйтесь с Дживсом');
INSERT INTO public.books (id, description, file_path, title) VALUES (85, 'Комедия о загородной жизни, где ошибки, недоразумения и любовь создают идеальный хаос. Вудхаус пишет легко, остроумно и с любовью к человеческим слабостям.', '/Вудхаус. Радость поутру.fb2', 'Радость поутру');
INSERT INTO public.books (id, description, file_path, title) VALUES (86, 'Берти снова в беде — и снова Дживс спасает положение. Вудхаус исследует, как лакей может быть умнее лорда — и как важно иметь рядом человека, который знает, что делать, когда ты не знаешь ничего.', '/Вудхаус. Так держать, Дживс!.fb2', 'Так держать, Дживс!');
INSERT INTO public.books (id, description, file_path, title) VALUES (87, 'Юмористическая повесть о том, как избавиться от назойливой тетки — с помощью Дживса, конечно. Вудхаус показывает, что даже самые страшные родственники не страшны, если у тебя есть гениальный план.', '/Вудхаус. Тетки - не джентльмены.fb2', 'Тетки - не джентльмены');
INSERT INTO public.books (id, description, file_path, title) VALUES (88, 'Еще одна история о спасении Берти от катастрофы — на этот раз связанной с театром, актрисами и украденной собакой. Вудхаус — мастер превращать хаос в комедию.', '/Вудхаус. Тысяча благодарностей, Дживс!.fb2', 'Тысяча благодарностей, Дживс!');
INSERT INTO public.books (id, description, file_path, title) VALUES (89, 'Роман о том, как Берти пытается защитить честь семьи — и почти терпит крах, если бы не Дживс. Вудхаус показывает, что настоящая честь — не в титулах, а в умении признать свою глупость.', '/Вудхаус. Фамильная честь Вустеров.fb2', 'Фамильная честь Вустеров');
INSERT INTO public.books (id, description, file_path, title) VALUES (90, 'Сборник рассказов, где Дживс — не просто лакей, а философ, психолог и стратег. Вудхаус создает героя, который спасает мир — один чай за раз.', '/Вудхаус. Этот неподражаемый Дживс.fb2', 'Этот неподражаемый Дживс');
INSERT INTO public.books (id, description, file_path, title) VALUES (91, 'Сборник стихов и песен Высоцкого — голос эпохи. От лирики до сатиры, от любви до бунта. Каждое стихотворение — как крик души, который слышали миллионы. Поэзия, которая не стареет.', '/Высоцкий. Я не люблю.fb2', 'Я не люблю');
INSERT INTO public.books (id, description, file_path, title) VALUES (92, 'Повесть о мальчике, который ненавидит школу, но любит столярное дело. Гавальда показывает, как важно найти свое призвание — даже если весь мир против. Книга о надежде, которая весит всего 35 килограмм — но поднимает целый мир.', '/Гавальда. 35 кило надежды.fb2', '35 кило надежды');
INSERT INTO public.books (id, description, file_path, title) VALUES (110, 'Роман о двух друзьях — монахе и поэте, — которые ищут истину разными путями. Гессе показывает, что духовность и чувственность — две стороны одной медали. Книга о гармонии противоположностей.', '/Гессе. Нарцисс и Златоуст.fb2', 'Нарцисс и Златоуст');
INSERT INTO public.books (id, description, file_path, title) VALUES (93, 'Лирические рассказы о любви, одиночестве и поиске дома. Гавальда пишет просто, тепло и пронзительно — о тех моментах, когда человеку просто нужно, чтобы его ждали.', '/Гавальда. Мне бы хотелось, чтобы меня кто-нибудь где-нибудь ждал… (сборник).fb2', 'Мне бы хотелось, чтобы меня кто-нибудь где-нибудь ждал… (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (94, 'Роман-исповедь о писателе, который голодает в Осло — физически и духовно. Гамсун исследует грань между гениальностью и безумием, между жизнью и смертью. Книга, которая вдохновила Кафку и Камю.', '/Гамсун. Голод.fb2', 'Голод');
INSERT INTO public.books (id, description, file_path, title) VALUES (95, 'Автобиография Махатмы Ганди — не просто мемуары, а философия жизни. Каждая глава — эксперимент с правдой, ненасилием и совестью. Книга, которая изменила мир.', '/Ганди. Моя жизнь, или История моих экспериментов с истиной.fb2', 'Моя жизнь, или История моих экспериментов с истиной');
INSERT INTO public.books (id, description, file_path, title) VALUES (96, 'Роман о любви, которая длится всю жизнь — даже когда пути расходятся. Ганн показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс.', '/Ганн. Где бы ты ни был.fb2', 'Где бы ты ни был');
INSERT INTO public.books (id, description, file_path, title) VALUES (97, 'Социальный роман о столкновении промышленного Севера и аграрного Юга Англии. Гаскелл исследует классовую борьбу, любовь и перемены. Книга, где личная драма переплетается с исторической.', '/Гаскелл. Север и Юг.fb2', 'Север и Юг');
INSERT INTO public.books (id, description, file_path, title) VALUES (98, 'Сборник сказок и легенд, где фантазия встречается с моралью. Гауф создает волшебные миры, населенные джиннами, карликами и принцессами. Книга для детей — и для взрослых, которые помнят, как верить в чудеса.', '/Гауф. Корабль привидений и другие истории.fb2', 'Корабль привидений и другие истории');
INSERT INTO public.books (id, description, file_path, title) VALUES (99, 'Фундаментальный труд Гегеля, где мышление исследуется как система категорий. Книга, которую называют "самой трудной в философии", — но именно она заложила основы диалектики и повлияла на всю европейскую мысль.', '/Гегель. Логика.fb2', 'Логика');
INSERT INTO public.books (id, description, file_path, title) VALUES (100, 'Гегель исследует путь сознания от чувственности до абсолютного знания. Книга, которая изменила философию: дух познает себя через историю, страдание и противоречия. Труд, требующий не прочтения, а проживания.', '/Гегель. Феноменология духа.fb2', 'Феноменология духа');
INSERT INTO public.books (id, description, file_path, title) VALUES (101, 'Фэнтези о богах, которые приехали в Америку с иммигрантами — и теперь борются за выживание. Гейман создает эпическую сагу, где мифология сталкивается с современностью. Книга о том, что боги живут там, где их помнят.', '/Гейман. Американские боги.fb2', 'Американские боги');
INSERT INTO public.books (id, description, file_path, title) VALUES (102, 'Сборник рассказов о чудовищах, феях и магии. Гейман показывает, что фантастика — не побег от реальности, а способ ее понять. Каждая история — как заклинание: короткое, но мощное.', '/Гейман. Фантастические создания (антология).fb2', 'Фантастические создания (антология)');
INSERT INTO public.books (id, description, file_path, title) VALUES (103, 'Сборник рассказов, где реальность трещит по швам. Гейман исследует страх, любовь, смерть и чудеса — с изяществом и жестокостью. Книга для тех, кто верит, что волшебство скрывается в мелочах.', '/Гейман. Хрупкие вещи.fb2', 'Хрупкие вещи');
INSERT INTO public.books (id, description, file_path, title) VALUES (104, 'Научная фантастика о контакте с инопланетной цивилизацией. Герберт показывает, как легко превратить контакт в жертвоприношение — и как трудно понять "другого". Книга, написанная с философской глубиной.', '/Герберт. Жертвенная звезда.fb2', 'Жертвенная звезда');
INSERT INTO public.books (id, description, file_path, title) VALUES (105, 'Хроника греко-персидских войн — первый труд, который можно назвать "историей" в современном смысле. Геродот рассказывает о битвах, чудесах и обычаях народов — с любопытством путешественника и точностью летописца.', '/Геродот. История.fb2', 'История');
INSERT INTO public.books (id, description, file_path, title) VALUES (106, 'Мемуары Герцена — энциклопедия русской интеллигенции XIX века. Автор исследует революцию, изгнание и поиск свободы. Книга, которая стала "библией русского либерализма".', '/Герцен. Былое и думы. Эмиграция.fb2', 'Былое и думы. Эмиграция');
INSERT INTO public.books (id, description, file_path, title) VALUES (107, 'Роман о любви, музыке и внутреннем мире. Гессе исследует, как искусство помогает преодолеть одиночество — и как трудно найти себя в мире, который требует масок. Книга, написанная с тонкостью и лиризмом.', '/Гессе. Гертруда.fb2', 'Гертруда');
INSERT INTO public.books (id, description, file_path, title) VALUES (108, 'Роман о становлении личности, где юноша ищет свой путь между светом и тьмой. Гессе показывает, что каждый человек должен пройти через ад, чтобы найти себя. Книга, которая стала библией поколения 1960-х.', '/Гессе. Демиан.fb2', 'Демиан');
INSERT INTO public.books (id, description, file_path, title) VALUES (111, 'Роман о юноше, который ищет смысл жизни в природе, любви и искусстве. Гессе создает поэтическую историю взросления — без морализаторства, с любовью к человеческой слабости.', '/Гессе. Петер Каменцинд (пер. Р. Эйвадис, 2019).fb2', 'Петер Каменцинд (пер. Р. Эйвадис, 2019)');
INSERT INTO public.books (id, description, file_path, title) VALUES (112, 'История художника, который теряет связь с семьей и самим собой. Гессе исследует, как творчество может разрушить жизнь — и как трудно вернуть утраченное. Книга, написанная с глубоким психологизмом.', '/Гессе. Росхальде.fb2', 'Росхальде');
INSERT INTO public.books (id, description, file_path, title) VALUES (113, 'Философская притча о поиске просветления. Гессе показывает, что истина — не в учениях, а в опыте. Книга, которая вдохновила миллионы на духовный поиск.', '/Гессе. Сиддхартха. Путешествие к земле Востока.fb2', 'Сиддхартха. Путешествие к земле Востока');
INSERT INTO public.books (id, description, file_path, title) VALUES (114, 'Роман о человеке, который чувствует себя чужим в мире. Гессе исследует двойственность природы: человек и волк, разум и инстинкт, жизнь и смерть. Книга, которая стала культовой для всех, кто чувствует себя изгоем.', '/Гессе. Степной волк.fb2', 'Степной волк');
INSERT INTO public.books (id, description, file_path, title) VALUES (115, 'Научно-философский труд, где Гете исследует природу цвета не как физик, а как художник. Книга, которая противостоит ньютоновской оптике — и предлагает видеть цвет как явление души.', '/Гете. Учение о цвете.fb2', 'Учение о цвете');
INSERT INTO public.books (id, description, file_path, title) VALUES (116, 'Трагедия о человеке, который продает душу дьяволу ради знаний и власти. Гете создает аллегорию человеческого стремления — и его цены. Книга, которая стала символом немецкой культуры.', '/Гете. Фауст.fb2', 'Фауст');
INSERT INTO public.books (id, description, file_path, title) VALUES (117, 'Сборник рассказов Гиппиус — о любви, смерти и метафизике. Автор исследует темную сторону человеческой души — с изяществом и жестокостью. Книга для тех, кто не боится смотреть в бездну.', '/Гиппиус. Ласковая кобра.fb2', 'Ласковая кобра');
INSERT INTO public.books (id, description, file_path, title) VALUES (118, 'Современные притчи о России, ее людях и судьбах. Глуховский показывает, как история повторяется — и как трудно найти правду в мире, где все относительно. Книга, написанная с болью и любовью к стране.', '/Глуховский. Рассказы о Родине.fb2', 'Рассказы о Родине');
INSERT INTO public.books (id, description, file_path, title) VALUES (119, 'Рассказ о чиновнике, который сходит с ума — и видит мир яснее, чем когда-либо. Гоголь создает сатиру на бюрократию и одиночество. Книга, где безумие — единственный способ остаться человеком.', '/Гоголь. Записки сумасшедшего.fb2', 'Записки сумасшедшего');
INSERT INTO public.books (id, description, file_path, title) VALUES (120, 'Роман-исповедь о жизни гейши в Японии XX века. Голден показывает, как красота становится товаром, а любовь — роскошью. Книга, написанная с изяществом и жестокой правдой.', '/Голден. Мемуары гейши.fb2', 'Мемуары гейши');
INSERT INTO public.books (id, description, file_path, title) VALUES (121, 'Роман о мальчике, который крадет, чтобы выжить — и находит в себе совесть. Голдинг исследует, как общество формирует мораль — и как легко ее потерять. Книга, написанная с состраданием и без иллюзий.', '/Голдинг. Воришка Мартин.fb2', 'Воришка Мартин');
INSERT INTO public.books (id, description, file_path, title) VALUES (122, 'Фантастика о встрече homo sapiens и неандертальцев. Голдинг показывает, как цивилизация рождается через насилие — и как легко потерять человечность. Книга-аллегория о природе прогресса.', '/Голдинг. Наследники.fb2', 'Наследники');
INSERT INTO public.books (id, description, file_path, title) VALUES (123, 'Антиутопия о группе мальчиков, оказавшихся на необитаемом острове. Голдинг показывает, как быстро цивилизация превращается в хаос — и как тонка грань между порядком и варварством. Книга, ставшая символом XX века.', '/Голдинг. Повелитель мух.fb2', 'Повелитель мух');
INSERT INTO public.books (id, description, file_path, title) VALUES (124, 'Роман о строительстве собора — и человеческих амбициях. Голдинг исследует, как вера, власть и искусство формируют историю. Книга, написанная с эпическим размахом и философской глубиной.', '/Голдинг. Шпиль.fb2', 'Шпиль');
INSERT INTO public.books (id, description, file_path, title) VALUES (125, 'Эпическая семейная хроника, где деньги, собственность и страсть разрушают отношения. Голсуорси показывает, как буржуазия создает и разрушает саму себя. Книга, ставшая классикой английской литературы.', '/Голсуорси. Сага о Форсайтах.fb2', 'Сага о Форсайтах');
INSERT INTO public.books (id, description, file_path, title) VALUES (126, 'Продолжение "Саги о Форсайтах" — о новом поколении, которое пытается жить по-другому. Голсуорси исследует, как меняется общество — и как трудно избавиться от наследия прошлого.', '/Голсуорси. Современная комедия.fb2', 'Современная комедия');
INSERT INTO public.books (id, description, file_path, title) VALUES (127, 'Исследование о художнице Наталье Гончаровой и ее связи с Пушкиным. Горбачева показывает, как искусство и поэзия переплетаются в русской культуре. Книга для ценителей эстетики и истории.', '/Горбачева. Гончарова и Пушкин.fb2', 'Гончарова и Пушкин');
INSERT INTO public.books (id, description, file_path, title) VALUES (128, 'Автобиографическая трилогия Горького — история становления личности в мире, где нет места слабости. Автор показывает, как выжить, когда все против тебя — и как не потерять человечность.', '/Горький. Детство. В людях. Мои университеты.fb2', 'Детство. В людях. Мои университеты');
INSERT INTO public.books (id, description, file_path, title) VALUES (129, 'Пьеса о людях, оказавшихся на самом дне общества. Горький исследует, что важнее — правда или иллюзия? Книга, которая задает главный вопрос: можно ли жить без надежды?', '/Горький. На дне.fb2', 'На дне');
INSERT INTO public.books (id, description, file_path, title) VALUES (130, 'Литературные портреты великих русских писателей и революционера. Горький показывает, как личность формирует эпоху — и как эпоха ломает личность. Книга, написанная с любовью и болью.', '/Горький. Толстой. Чехов. Ленин (сборник).fb2', 'Толстой. Чехов. Ленин (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (131, 'Роман о войне, идеализме и предательстве. Грин показывает, как благие намерения разрушают Вьетнам — и как трудно остаться честным в мире, где все серое. Книга, ставшая пророчеством о вмешательстве Запада.', '/Грин. Тихий американец.fb2', 'Тихий американец');
INSERT INTO public.books (id, description, file_path, title) VALUES (132, 'Повесть, написанная от лица человека, ожидающего казни. Гюго создает мощный протест против смертной казни — через личную трагедию. Книга, которая заставляет задуматься о цене жизни.', '/Гюго. Последний день приговоренного к смерти.fb2', 'Последний день приговоренного к смерти');
INSERT INTO public.books (id, description, file_path, title) VALUES (133, 'Роман-эпопея о любви, судьбе и архитектуре. Гюго показывает, как камень может быть живее человека — и как легко разрушить красоту. Книга, которая спасла собор от разрушения.', '/Гюго. Собор Парижской Богоматери.fb2', 'Собор Парижской Богоматери');
INSERT INTO public.books (id, description, file_path, title) VALUES (134, 'Сборник записей великого гения — о природе, анатомии, перспективе и красоте. Да Винчи исследует мир как художник и ученый одновременно. Книга, которая показывает, что гений видит то, что скрыто от других.', '/да Винчи. О науке и искусстве.fb2', 'О науке и искусстве');
INSERT INTO public.books (id, description, file_path, title) VALUES (135, 'Исследование о том, почему одни цивилизации победили другие. Даймонд показывает, что судьба народов определяется не расой, а географией, технологиями и биологией. Книга, перевернувшая представление об истории.', '/Даймонд. Ружья, микробы и сталь.fb2', 'Ружья, микробы и сталь');
INSERT INTO public.books (id, description, file_path, title) VALUES (136, 'Юридические выступления Плевако — образец ораторского искусства. Автор защищает невиновных, обличает порок и показывает, что правосудие — это не закон, а совесть. Книга для тех, кто верит в силу слова.', '/Плевако. Избранные речи.fb2', 'Избранные речи');
INSERT INTO public.books (id, description, file_path, title) VALUES (137, 'Готический роман о двух сестрах, живущих в изоляции после трагедии. Джексон создает атмосферу паранойи, где реальность и безумие переплетаются. Книга, написанная с изящной жестокостью.', '/Джексон. Мы всегда жили в замке.fb2', 'Мы всегда жили в замке');
INSERT INTO public.books (id, description, file_path, title) VALUES (138, 'Экспериментальная проза Джойса — день из жизни Леопольда Блума. Автор исследует поток сознания, мифологию и быт Дублина. Книга, которая изменила литературу — и требует не чтения, а проживания.', '/Джойс. Улисс. Том I.fb2', 'Улисс. Том I');
INSERT INTO public.books (id, description, file_path, title) VALUES (139, 'Продолжение эпического путешествия Блума и Стивена Дедала. Джойс играет с языком, формой и смыслом — создавая текст, который стал символом модернизма. Книга, которую нужно перечитывать всю жизнь.', '/Джойс. Улисс. Том II.fb2', 'Улисс. Том II');
INSERT INTO public.books (id, description, file_path, title) VALUES (140, 'Готические рассказы Диккенса — о призраках, тайнах и раскаянии. Автор показывает, что настоящее привидение — не в доме, а в душе. Книга, написанная с юмором и жутью одновременно.', '/Диккенс. Комната с привидениями (сборник).fb2', 'Комната с привидениями (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (141, 'Юмористическая сага о путешествиях чудаковатого клуба. Диккенс создает галерею персонажей, которые вызывают улыбку даже в самый хмурый день. Книга, с которой началась его литературная слава.', '/Диккенс. Посмертные записки Пиквикского клуба.fb2', 'Посмертные записки Пиквикского клуба');
INSERT INTO public.books (id, description, file_path, title) VALUES (142, 'Роман о сироте, который выживает в лондонском аду. Диккенс показывает, как общество создает преступников — и как трудно остаться чистым в мире грязи. Книга, ставшая символом социальной справедливости.', '/Диккенс. Приключения Оливера Твиста.fb2', 'Приключения Оливера Твиста');
INSERT INTO public.books (id, description, file_path, title) VALUES (143, 'Биографии древних мыслителей — от Пифагора до Эпикура. Диоген Лаэртский создает портреты гениев, их странных привычек и вечных идей. Книга, которая показывает: философия — это жизнь.', '/Диоген Лаэртский. О жизни, учениях и изречениях знаменитых философов.fb2', 'О жизни, учениях и изречениях знаменитых философов');
INSERT INTO public.books (id, description, file_path, title) VALUES (144, 'Сборник рассказов о величайшем детективе. Конан Дойл создает загадки, которые решаются логикой — и показывает, что правда всегда сложнее, чем кажется. Книга, породившая жанр детектива.', '/Дойл. Приключения Шерлока Холмса. Возвращение Шерлока Холмса.fb2', 'Приключения Шерлока Холмса. Возвращение Шерлока Холмса');
INSERT INTO public.books (id, description, file_path, title) VALUES (145, 'Роман-предупреждение о революции, которая разрушает все — даже тех, кто ее делает. Достоевский исследует идеологию, безумие и русскую душу. Книга, которая остается актуальной — потому что бесы не ушли, они внутри нас.', '/Достоевский. Бесы.fb2', 'Бесы');
INSERT INTO public.books (id, description, file_path, title) VALUES (146, 'Философский роман о вере, сомнении и свободе. Достоевский задает главные вопросы: есть ли Бог? В чем смысл страдания? Кто виноват в зле? Книга, которую называют "энциклопедией русской души".', '/Достоевский. Братья Карамазовы.fb2', 'Братья Карамазовы');
INSERT INTO public.books (id, description, file_path, title) VALUES (147, 'Роман о "положительно прекрасном человеке", который пытается жить по евангельским заповедям — и разрушается в мире зла. Достоевский показывает, что доброта — не слабость, а величайший подвиг. Книга, написанная с болью и любовью.', '/Достоевский. Идиот.fb2', 'Идиот');
INSERT INTO public.books (id, description, file_path, title) VALUES (148, 'Роман о юноше, который ищет отца, смысл и себя. Достоевский исследует, как формируется личность в мире, где нет опоры. Книга, написанная с психологической глубиной и философской остротой.', '/Достоевский. Подросток.fb2', 'Подросток');
INSERT INTO public.books (id, description, file_path, title) VALUES (149, 'Роман о студенте, который убивает — и наказывает себя совестью. Достоевский показывает, что истинное наказание — не тюрьма, а внутренняя мука. Книга, ставшая символом борьбы добра и зла в человеке.', '/Достоевский. Преступление и наказание.fb2', 'Преступление и наказание');
INSERT INTO public.books (id, description, file_path, title) VALUES (150, 'Эссе и размышления Достоевского о детях, страдании и Боге. Автор задает главный вопрос: можно ли оправдать мир, где плачут дети? Книга, написанная с болью и верой одновременно.', '/Достоевский. Слезинка ребенка. Дневник писателя.fb2', 'Слезинка ребенка. Дневник писателя');
INSERT INTO public.books (id, description, file_path, title) VALUES (151, 'Фундаментальный труд, заложивший основы социологии как науки. Дюркгейм учит: общество — это не сумма индивидов, а реальность, которая формирует их. Книга, которая изменила понимание общества.', '/Дюркгейм. Правила социологического метода.fb2', 'Правила социологического метода');
INSERT INTO public.books (id, description, file_path, title) VALUES (152, 'Исследование о причинах самоубийств — не психологических, а социальных. Дюркгейм показывает, что человек умирает не от личной трагедии, а от разрыва с обществом. Книга, ставшая классикой социологии.', '/Дюркгейм. Самоубийство.fb2', 'Самоубийство');
INSERT INTO public.books (id, description, file_path, title) VALUES (153, 'Сборник стихов Есенина — лирика о деревне, любви и тоске. Автор создает образ России, которая исчезает — и чувств, которые остаются. Поэзия, пропитанная болью и красотой.', '/Есенин. Эта жизнь мне только снится.fb2', 'Эта жизнь мне только снится');
INSERT INTO public.books (id, description, file_path, title) VALUES (154, 'Научная фантастика о путешествиях к звездам и поиске смысла. Ефремов показывает, что будущее — не технологии, а гармония человека с миром. Книга, написанная с оптимизмом и верой в человечество.', '/Ефремов. Звездные корабли.fb2', 'Звездные корабли');
INSERT INTO public.books (id, description, file_path, title) VALUES (155, 'Антиутопия о тоталитарном обществе будущего. Ефремов исследует, как система ломает личность — и как важно сохранить человечность. Книга, написанная с тревогой и надеждой.', '/Ефремов. Час быка.fb2', 'Час быка');
INSERT INTO public.books (id, description, file_path, title) VALUES (156, 'Роман о рынке, где еда становится символом жизни. Золя показывает, как люди живут, любят и страдают среди изобилия. Книга, написанная с любовью к деталям и состраданием к людям.', '/Золя. Чрево Парижа.fb2', 'Чрево Парижа');
INSERT INTO public.books (id, description, file_path, title) VALUES (157, 'Юмористические рассказы о советской жизни. Зощенко создает галерею чудаков, бюрократов и мечтателей — с иронией и любовью. Книга, которая смеется над абсурдом — и плачет от боли.', '/Зощенко. Перед восходом солнца.fb2', 'Перед восходом солнца');
INSERT INTO public.books (id, description, file_path, title) VALUES (158, 'Сатира на "культурное" общество, где форма важнее содержания. Зощенко показывает, как легко превратить культуру в маску — и как трудно остаться человеком. Книга, написанная с остроумием и грустью.', '/Зощенко. Прелести культуры.fb2', 'Прелести культуры');
INSERT INTO public.books (id, description, file_path, title) VALUES (159, 'Современный роман о Москве, где реальность и фантазия переплетаются. Иванов создает мир, где каждый герой — маска, а истина скрыта за словами. Книга, написанная с дерзостью и иронией.', '/Иванов. Блуда и МУДО.fb2', 'Блуда и МУДО');
INSERT INTO public.books (id, description, file_path, title) VALUES (160, 'Роман о поколении, которое потеряло ориентиры. Иванов исследует, как жить, когда нет будущего — и как найти себя в мире, который рушится. Книга, написанная с болью и надеждой.', '/Иванов. Ненастье.fb2', 'Ненастье');
INSERT INTO public.books (id, description, file_path, title) VALUES (161, 'Роман о студенческой жизни в 1990-е — с юмором, грязью и поэзией. Иванов показывает, как молодость пытается выжить в мире, который не хочет ее понять. Книга, ставшая культовой для поколения.', '/Иванов. Общага-на-Крови.fb2', 'Общага-на-Крови');
INSERT INTO public.books (id, description, file_path, title) VALUES (162, 'Роман о художнике, который ищет цвет и форму — и находит себя. Иличевский исследует, как искусство спасает от реальности — и как трудно остаться верным себе. Книга, написанная с любовью к живописи.', '/Иличевский. Матисс.fb2', 'Матисс');
INSERT INTO public.books (id, description, file_path, title) VALUES (163, 'Сатира на советскую действительность, где бывший аристократ ищет сокровища в стульях. Ильф и Петров создают комедию, где абсурд — единственный способ выжить. Книга, которая смеется над всем — и никого не щадит.', '/Ильф, Петров. 12 стульев.fb2', '12 стульев');
INSERT INTO public.books (id, description, file_path, title) VALUES (164, 'Роман о гее, который переживает смерть партнера — и пытается жить дальше. Ишервуд показывает, как одиночество становится частью личности — и как трудно найти новую любовь. Книга, написанная с тонкостью и болью.', '/Ишервуд. Одинокий мужчина.fb2', 'Одинокий мужчина');
INSERT INTO public.books (id, description, file_path, title) VALUES (165, 'Полуавтобиографические рассказы о жизни в Берлине накануне нацизма. Ишервуд создает портрет города, где веселье скрывает надвигающуюся катастрофу. Книга, ставшая основой мюзикла "Кабаре".', '/Ишервуд. Прощай, Берлин.fb2', 'Прощай, Берлин');
INSERT INTO public.books (id, description, file_path, title) VALUES (166, 'Биография гениального изобретателя, который опередил свое время. Ишков показывает, как наука и безумие переплетаются в одном человеке. Книга о том, что гений часто платит за свое видение.', '/Ишков. Никола Тесла. Изобретатель тайн.fb2', 'Никола Тесла. Изобретатель тайн');
INSERT INTO public.books (id, description, file_path, title) VALUES (167, 'Роман-игра, где читатель становится героем. Кальвино исследует природу чтения, сюжета и авторства. Книга, которая ломает четвертую стену — и заставляет задуматься: кто на самом деле читает?', '/Кальвино. Если однажды зимней ночью путник….fb2', 'Если однажды зимней ночью путник…');
INSERT INTO public.books (id, description, file_path, title) VALUES (168, 'Эссе о метафизическом бунте и пьеса о преступлении без причины. Камю исследует, как человек бунтует против абсурда — и как легко стать жертвой собственного отчаяния. Книга, написанная с философской глубиной.', '/Камю. Бунтующий человек. Недоразумение.fb2', 'Бунтующий человек. Недоразумение');
INSERT INTO public.books (id, description, file_path, title) VALUES (169, 'Сборник эссе и рассказов — о солнце, море и человеческой природе. Камю показывает, что красота — это ответ на абсурд. Книга, написанная с любовью к жизни.', '/Камю. Изнанка и лицо. Брачный пир. Лето.fb2', 'Изнанка и лицо. Брачный пир. Лето');
INSERT INTO public.books (id, description, file_path, title) VALUES (170, 'Эссе о двойственности мира: свет и тень, радость и боль. Камю исследует, как человек находит гармонию в противоречиях. Книга, написанная с поэтической точностью.', '/Камю. Изнанка и лицо.fb2', 'Изнанка и лицо');
INSERT INTO public.books (id, description, file_path, title) VALUES (171, 'Роман-исповедь о судье, который признается в своих грехах. Камю показывает, что все мы виноваты — и только признание делает нас свободными. Книга, написанная с горькой иронией.', '/Камю. Падение. Изгнание и царство.fb2', 'Падение. Изгнание и царство');
INSERT INTO public.books (id, description, file_path, title) VALUES (172, 'Автобиографический роман о детстве в Алжире. Камю исследует, как формируется личность в мире бедности и любви. Книга, оставшаяся незавершенной — как сама жизнь.', '/Камю. Первый человек.fb2', 'Первый человек');
INSERT INTO public.books (id, description, file_path, title) VALUES (173, 'Роман, эссе и пьеса — три взгляда на абсурд. Камю показывает, что жизнь бессмысленна — и именно поэтому стоит жить. Книга, ставшая манифестом экзистенциализма.', '/Камю. Посторонний. Миф о Сизифе. Калигула.fb2', 'Посторонний. Миф о Сизифе. Калигула');
INSERT INTO public.books (id, description, file_path, title) VALUES (174, 'Ранний роман о человеке, который ищет счастье через смерть. Камю исследует, можно ли найти смысл в мире, где все кончается. Книга, написанная с юношеской страстью и отчаянием.', '/Камю. Счастливая смерть.fb2', 'Счастливая смерть');
INSERT INTO public.books (id, description, file_path, title) VALUES (175, 'Философский трактат, где Кант пытается доказать существование Бога через разум. Автор показывает, что вера — не противоположность разума, а его предел. Книга, изменившая теологию.', '/Кант. Доказательство бытия Бога.fb2', 'Доказательство бытия Бога');
INSERT INTO public.books (id, description, file_path, title) VALUES (176, 'Труд о красоте, вкусе и цели в природе. Кант исследует, как человек воспринимает прекрасное — и почему оно объединяет всех. Книга, заложившая основы эстетики.', '/Кант. Критика способности суждения.fb2.fb2', 'Критика способности суждения.fb2');
INSERT INTO public.books (id, description, file_path, title) VALUES (177, 'Фантастика о контакте с инопланетной цивилизацией. Кауфман и Спунер показывают, как легко разрушить чужую культуру — и как трудно понять "другого". Книга, написанная с философской глубиной.', '/Кауфман, Спунер. Разбитые звезды.fb2', 'Разбитые звезды');
INSERT INTO public.books (id, description, file_path, title) VALUES (178, 'Новелла о человеке, который превращается в насекомое — и становится ближе к своей семье. Кафка исследует отчуждение, вину и абсурд. Книга, ставшая символом XX века.', '/Кафка. Превращение.fb2', 'Превращение');
INSERT INTO public.books (id, description, file_path, title) VALUES (179, 'Криминальный роман о страсти, предательстве и судьбе. Кейн создает историю, где любовь ведет к убийству — и где нет невиновных. Книга, написанная с жестокой поэзией.', '/Кейн. Почтальон всегда звонит дважды.fb2', 'Почтальон всегда звонит дважды');
INSERT INTO public.books (id, description, file_path, title) VALUES (180, 'Христианский трактат о смирении, молитве и внутреннем пути. Кемпийский Фома учит: истинная жизнь — не в мире, а в Боге. Книга, ставшая одной из самых читаемых в истории христианства.', '/Кемпийский Фома. О подражании Христу.fb2', 'О подражании Христу');
INSERT INTO public.books (id, description, file_path, title) VALUES (181, 'Нон-фикшн о человеке с раздвоением личности, который совершил преступления — и не помнил о них. Киз исследует, что такое "я" — и кто несет ответственность за поступки. Книга, ставшая культовой.', '/Киз. Таинственная история Билли Миллигана.fb2', 'Таинственная история Билли Миллигана');
INSERT INTO public.books (id, description, file_path, title) VALUES (182, 'Фэнтези о тюремном надзирателе и заключенном с даром исцеления. Кинг показывает, что чудеса случаются даже в аду — и что истинное наказание — не смерть, а боль. Книга, написанная с состраданием и надеждой.', '/Кинг. Зеленая миля.fb2', 'Зеленая миля');
INSERT INTO public.books (id, description, file_path, title) VALUES (183, 'Научная фантастика о контакте с инопланетной цивилизацией, которая "спасает" человечество. Кларк исследует, что значит быть человеком — и стоит ли спасение потери свободы. Книга, написанная с грустью и величием.', '/Кларк. Конец детства.fb2', 'Конец детства');
INSERT INTO public.books (id, description, file_path, title) VALUES (184, 'Фантастика о путешествии к черной дыре. Клемент показывает, как наука встречается с неизвестным — и как легко потерять себя в космосе. Книга, написанная с любовью к физике.', '/Клемент. Экспедиция «Тяготение».fb2', 'Экспедиция «Тяготение»');
INSERT INTO public.books (id, description, file_path, title) VALUES (185, 'Пьесы о подростках, которые играют в любовь — и разрушают друг друга. Кокто исследует, как страсть превращается в разрушение — и как трудно вырасти. Книга, написанная с изящной жестокостью.', '/Кокто. Ужасные дети. Адская машина.fb2', 'Ужасные дети. Адская машина');
INSERT INTO public.books (id, description, file_path, title) VALUES (186, 'Детектив о привидениях, которые оживают — и убивают. Коллинз создает атмосферу готического ужаса, где прошлое мстит настоящему. Книга, написанная с мастерством и напряжением.', '/Коллинз. Мертвая комната.fb2', 'Мертвая комната');
INSERT INTO public.books (id, description, file_path, title) VALUES (187, 'Юридические выступления Кони — образец ораторского искусства. Автор защищает невиновных, обличает порок и показывает, что правосудие — это не закон, а совесть. Книга для тех, кто верит в силу слова.', '/Кони. Лучшие речи.fb2', 'Лучшие речи');
INSERT INTO public.books (id, description, file_path, title) VALUES (188, 'Роман о писателе, который продает душу дьяволу ради славы. Корелли исследует, что важнее — успех или душа? Книга, ставшая бестселлером конца XIX века.', '/Корелли. Скорбь Сатаны.fb2', 'Скорбь Сатаны');
INSERT INTO public.books (id, description, file_path, title) VALUES (189, 'Сборник рассказов, где реальность трещит по швам. Кортасар играет с формой, временем и читателем — создавая тексты, которые требуют участия. Книга для тех, кто любит литературу как игру.', '/Кортасар. Счастливчики.fb2', 'Счастливчики');
INSERT INTO public.books (id, description, file_path, title) VALUES (190, 'Притча о юноше, который ищет сокровище — и находит себя. Коэльо показывает, что путь важнее цели — и что Вселенная помогает тем, кто следует за мечтой. Книга, ставшая бестселлером мирового масштаба.', '/Коэльо. Алхимик.fb2', 'Алхимик');
INSERT INTO public.books (id, description, file_path, title) VALUES (191, 'Роман о девушке, которая ищет магию — и находит любовь. Коэльо исследует, как вера и страсть формируют судьбу. Книга, написанная с поэтической простотой.', '/Коэльо. Брида.fb2', 'Брида');
INSERT INTO public.books (id, description, file_path, title) VALUES (192, 'Сборник стихов Крик — о любви, боли и поиске себя. Автор исследует, как страсть разрушает и создает одновременно. Книга, написанная с дерзостью и нежностью.', '/Крик. Что за безумное стремленье.fb2', 'Что за безумное стремленье');
INSERT INTO public.books (id, description, file_path, title) VALUES (193, 'Эссе о том, что мораль возможна без государства. Кропоткин показывает, что сотрудничество — естественное состояние человека. Книга, ставшая библией анархистов.', '/Кропоткин. Анархия и нравственность (сборник).fb2', 'Анархия и нравственность (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (194, 'Научно-популярная книга о великих микробиологах. Крюи показывает, как наука спасает человечество — и как легко забыть тех, кто это сделал. Книга, написанная с уважением к гениям.', '/Крюи. Охотники за микробами.fb2', 'Охотники за микробами');
INSERT INTO public.books (id, description, file_path, title) VALUES (245, 'Полемика с Прудоном — где Маркс показывает, что экономика определяет философию, а не наоборот. Книга, заложившая основы исторического материализма.', '/Маркс. Нищета философии.fb2', 'Нищета философии');
INSERT INTO public.books (id, description, file_path, title) VALUES (195, 'Рассказ о любви, которая длится всю жизнь — даже после смерти. Куприн исследует, как память сохраняет человека — и как трудно отпустить прошлое. Книга, написанная с лиризмом и болью.', '/Куприн. Звезда Соломона.fb2', 'Звезда Соломона');
INSERT INTO public.books (id, description, file_path, title) VALUES (196, 'Повесть о школе, где дети и учителя ищут смысл. Кучерская показывает, как искусство спасает от серости — и как трудно остаться верным себе. Книга, написанная с любовью к детям.', '/Кучерская. Плач по уехавшей учительнице рисования.fb2', 'Плач по уехавшей учительнице рисования');
INSERT INTO public.books (id, description, file_path, title) VALUES (197, 'Роман о женщине, которая живет своей жизнью — вопреки всему. Кучерская исследует, как найти счастье в маленьких радостях — и как важно не сдаваться. Книга, написанная с теплотой и юмором.', '/Кучерская. Тетя Мотя.fb2', 'Тетя Мотя');
INSERT INTO public.books (id, description, file_path, title) VALUES (198, 'Кульминация мифов Лавкрафта — о древнем боге, который спит под водой. Автор создает атмосферу космического ужаса, где человек — ничто перед вселенной. Книга, ставшая основой хоррор-жанра.', '/Лавкрафт. Зов Ктулху.fb2', 'Зов Ктулху');
INSERT INTO public.books (id, description, file_path, title) VALUES (199, 'Сборник рассказов о древних богах, которые ждут своего часа. Лавкрафт исследует страх перед неизвестным — и показывает, что реальность тоньше, чем кажется. Книга, породившая целую мифологию.', '/Лавкрафт. Мифы Ктулху.fb2', 'Мифы Ктулху');
INSERT INTO public.books (id, description, file_path, title) VALUES (200, 'Фантастический сборник, вдохновленный мифами Лавкрафта. Авторы исследуют, что скрыто за гранью реальности — и как легко сойти с ума, заглянув в бездну. Книга для ценителей ужаса.', '/Лавкрафт. Некрономикон. Книга запретных тайн (сборник).fb2', 'Некрономикон. Книга запретных тайн (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (201, 'Сборник рассказов, где сны становятся порталами в другие миры. Лавкрафт показывает, что подсознание — опаснее реальности. Книга, написанная с атмосферой неотвратимого ужаса.', '/Лавкрафт. Сны Ктулху.fb2', 'Сны Ктулху');
INSERT INTO public.books (id, description, file_path, title) VALUES (202, 'Роман о физике, который видит мир иначе. Лайтман исследует, как наука и поэзия переплетаются в одном человеке. Книга, написанная с любовью к науке и фантазии.', '/Лайтман. Сны Эйнштейна.fb2', 'Сны Эйнштейна');
INSERT INTO public.books (id, description, file_path, title) VALUES (203, 'Приключения джентльмена-грабителя, который обманывает всех — и остается героем. Леблан создает образ, который стал символом французского шарма и остроумия. Книга, написанная с легкостью и дерзостью.', '/Леблан. Арсен Люпен (сборник).fb2', 'Арсен Люпен (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (204, 'Философская фантастика о встрече с инопланетной цивилизацией, которая не хочет контакта. Лем исследует, как человек реагирует на абсолютное равнодушие вселенной. Книга, написанная с горькой иронией.', '/Лем. Абсолютная пустота.fb2', 'Абсолютная пустота');
INSERT INTO public.books (id, description, file_path, title) VALUES (205, 'Роман о космонавте, который возвращается на Землю через 100 лет. Лем показывает, как общество меняется — и как трудно найти себя в мире, который тебя забыл. Книга, написанная с тоской и мудростью.', '/Лем. Возвращение со звезд.fb2', 'Возвращение со звезд');
INSERT INTO public.books (id, description, file_path, title) VALUES (206, 'Научная фантастика о попытке расшифровать послание от инопланетян. Лем исследует, как наука встречается с верой — и как легко ошибиться, ища смысл. Книга, написанная с философской глубиной.', '/Лем. Глас Господа.fb2', 'Глас Господа');
INSERT INTO public.books (id, description, file_path, title) VALUES (207, 'Философская проза о суперинтеллекте, который отказывается от человечества. Лем задает главный вопрос: зачем развиваться, если цель неясна? Книга, написанная с холодной логикой и болью.', '/Лем. ГОЛЕМ XIV.fb2', 'ГОЛЕМ XIV');
INSERT INTO public.books (id, description, file_path, title) VALUES (208, 'Сатирические рассказы о космических путешествиях. Лем высмеивает человеческую глупость — через призму инопланетных цивилизаций. Книга, написанная с остроумием и гневом.', '/Лем. Звездные дневники Ийона Тихого (сборник).fb2', 'Звездные дневники Ийона Тихого (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (209, 'Научная фантастика о контакте с неорганической жизнью. Лем показывает, что разум может быть нечеловеческим — и что победа не всегда возможна. Книга, написанная с научной точностью и философской глубиной.', '/Лем. Непобедимый.fb2', 'Непобедимый');
INSERT INTO public.books (id, description, file_path, title) VALUES (210, 'Рассказ о космическом корабле, который становится жертвой неизвестного врага. Лем исследует, как страх разрушает разум — и как трудно выжить в пустоте. Книга, написанная с напряжением и ужасом.', '/Лем. Охота.fb2', 'Охота');
INSERT INTO public.books (id, description, file_path, title) VALUES (211, 'Фантастика о космонавте, который сталкивается с неизвестным. Лем показывает, что космос — не романтика, а испытание на прочность. Книга, написанная с реализмом и философией.', '/Лем. Рассказы о пилоте Пирксе (сборник).fb2', 'Рассказы о пилоте Пирксе (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (212, 'Роман о планете-океане, которая читает мысли. Лем исследует, как человек встречается с "другим" — и как легко сойти с ума, пытаясь понять непонятное. Книга, ставшая классикой мировой фантастики.', '/Лем. Солярис.fb2', 'Солярис');
INSERT INTO public.books (id, description, file_path, title) VALUES (213, 'Философская проза о будущем технологий. Лем предсказывает искусственный интеллект, виртуальную реальность и кризис гуманизма. Книга, написанная с пророческой точностью.', '/Лем. Сумма технологии.fb2', 'Сумма технологии');
INSERT INTO public.books (id, description, file_path, title) VALUES (214, 'Сатира о будущем, где реальность заменяют галлюцинации. Лем показывает, как легко создать иллюзию рая — и как трудно жить в правде. Книга, написанная с горьким юмором.', '/Лем. Футурологический конгресс.fb2', 'Футурологический конгресс');
INSERT INTO public.books (id, description, file_path, title) VALUES (215, 'Научная фантастика о контакте с инопланетной цивилизацией, которая скрывает правду. Лем исследует, как информация становится оружием — и как трудно понять "другого". Книга, написанная с напряжением и философией.', '/Лем. Эдем.fb2', 'Эдем');
INSERT INTO public.books (id, description, file_path, title) VALUES (216, 'Политический трактат, где Ленин анализирует причины мировой войны. Автор показывает, что империализм — это не политика, а экономика. Книга, изменившая ход истории.', '/Ленин. Империализм, как высшая стадия капитализма.fb2', 'Империализм, как высшая стадия капитализма');
INSERT INTO public.books (id, description, file_path, title) VALUES (217, 'Поэма о великой битве 1812 года. Лермонтов создает эпический образ войны — без героизации, с болью и правдой. Стихи, которые стали символом русской военной поэзии.', '/Лермонтов. Бородино.fb2', 'Бородино');
INSERT INTO public.books (id, description, file_path, title) VALUES (218, 'Повесть о страсти, которая ведет к преступлению. Лесков показывает, как любовь разрушает все — даже того, кто ее испытывает. Книга, написанная с драматизмом и психологизмом.', '/Лесков. Леди Макбет Мценского уезда.fb2', 'Леди Макбет Мценского уезда');
INSERT INTO public.books (id, description, file_path, title) VALUES (219, 'Роман о взрослении Скаут Финч — и разочаровании в отце. Ли исследует, как идеалы сталкиваются с реальностью — и как трудно остаться честным в мире, который несправедлив. Книга, ставшая классикой американской литературы.', '/Ли. Пойди поставь сторожа.fb2', 'Пойди поставь сторожа');
INSERT INTO public.books (id, description, file_path, title) VALUES (220, 'Роман о человеке, который знает дату своей смерти — и пытается жить. Липскеров исследует, как страх формирует судьбу — и как важно найти смысл, даже если время ограничено. Книга, написанная с юмором и болью.', '/Липскеров. Леонид обязательно умрет.fb2', 'Леонид обязательно умрет');
INSERT INTO public.books (id, description, file_path, title) VALUES (221, 'Мемуары академика Лихачёва — о науке, культуре и совести. Автор показывает, как жить с достоинством в мире, который часто не ценит его. Книга, написанная с мудростью и любовью к России.', '/Лихачёв. О жизни (Воспоминания).fb2', 'О жизни (Воспоминания)');
INSERT INTO public.books (id, description, file_path, title) VALUES (222, 'Две повести о волке и собаке, которые ищут свой путь. Лондон показывает, как природа и воспитание формируют судьбу — и как трудно найти дом. Книга, написанная с любовью к дикой природе.', '/Лондон. Белый Клык. Зов предков.fb2', 'Белый Клык. Зов предков');
INSERT INTO public.books (id, description, file_path, title) VALUES (223, 'Роман о земледельце, который пытается победить пустыню. Лондон исследует, как человек борется с природой — и как легко проиграть. Книга, написанная с реализмом и трагизмом.', '/Лондон. Лунная долина.fb2', 'Лунная долина');
INSERT INTO public.books (id, description, file_path, title) VALUES (224, 'Роман о женщине, которая строит дом — и находит себя. Лондон показывает, как труд и любовь создают гармонию — даже в мире, который против тебя. Книга, написанная с теплотой и силой.', '/Лондон. Маленькая хозяйка Большого дома.fb2', 'Маленькая хозяйка Большого дома');
INSERT INTO public.books (id, description, file_path, title) VALUES (225, 'Научная фантастика о контакте с инопланетной цивилизацией. Лондон исследует, как легко разрушить чужую культуру — и как трудно понять "другого". Книга, написанная с философской глубиной.', '/Лондон. Странник по звездам.fb2', 'Странник по звездам');
INSERT INTO public.books (id, description, file_path, title) VALUES (226, 'Научно-популярная книга о поведении животных. Лоренц показывает, как инстинкты управляют жизнью — и как человек не так уж отличается от зверей. Книга, написанная с любовью к науке.', '/Лоренц. Кольцо царя Соломона.fb2', 'Кольцо царя Соломона');
INSERT INTO public.books (id, description, file_path, title) VALUES (227, 'Исследование о жизни русского дворянства. Лотман показывает, как культура формирует личность — и как трудно понять прошлое. Книга, написанная с эрудицией и любовью к деталям.', '/Лотман. Беседы о русской культуре Быт и традиции русского дворянства (XVIII – начало XIX века).fb2', 'Беседы о русской культуре Быт и традиции русского дворянства (XVIII – начало XIX века)');
INSERT INTO public.books (id, description, file_path, title) VALUES (228, 'Поэма о мире, построенном на атомах и пустоте. Лукреций предвосхищает науку Нового времени — и учит, что смерть не страшна, потому что ее нет. Книга, написанная с поэтической силой.', '/Лукреций. О природе вещей.fb2', 'О природе вещей');
INSERT INTO public.books (id, description, file_path, title) VALUES (229, 'Автобиографическая проза о любви, потере и вере. Льюис показывает, как боль открывает путь к Богу — и как трудно принять утрату. Книга, написанная с честностью и глубиной.', '/Льюис. Настигнут радостью. Исследуя горе.fb2', 'Настигнут радостью. Исследуя горе');
INSERT INTO public.books (id, description, file_path, title) VALUES (230, 'Философская проза о том, как маски становятся лицами. Льюис исследует, как человек теряет себя — и как важно найти свое истинное лицо. Книга, написанная с мудростью и поэзией.', '/Льюис. Пока мы лиц не обрели.fb2', 'Пока мы лиц не обрели');
INSERT INTO public.books (id, description, file_path, title) VALUES (231, 'Современная интерпретация сказки — о девушке, которая ищет свободу. Майер показывает, что башня — не тюрьма, а выбор. Книга, написанная с феминистским подтекстом и юмором.', '/Майер. Рапунцель.fb2', 'Рапунцель');
INSERT INTO public.books (id, description, file_path, title) VALUES (232, 'Мистический роман о встрече с потусторонним. Майринк исследует, как реальность трещит по швам — и как легко сойти с ума, заглянув в бездну. Книга, написанная с атмосферой готического ужаса.', '/Майринк. Ангел западного окна.fb2', 'Ангел западного окна');
INSERT INTO public.books (id, description, file_path, title) VALUES (233, 'Роман о легендарном существе, созданном из глины. Майринк исследует, что значит быть человеком — и как легко потерять душу. Книга, ставшая основой мифа о Големе.', '/Майринк. Голем.fb2', 'Голем');
INSERT INTO public.books (id, description, file_path, title) VALUES (234, 'Роман о глухонемом, который становится исповедником для всех. Маккаллерс показывает, как одиночество объединяет людей — и как трудно найти понимание. Книга, написанная с состраданием и болью.', '/Маккаллерс. Сердце - одинокий охотник.fb2', 'Сердце - одинокий охотник');
INSERT INTO public.books (id, description, file_path, title) VALUES (235, 'Исследование о русской мифологии. Максимов показывает, как вера и суеверия формируют культуру — и как трудно отделить миф от реальности. Книга, написанная с любовью к народной традиции.', '/Максимов. Нечистая, неведомая и крестная сила.fb2', 'Нечистая, неведомая и крестная сила');
INSERT INTO public.books (id, description, file_path, title) VALUES (236, 'Мемуары Мандельштама — о поэзии, политике и личной трагедии. Автор показывает, как искусство выживает в мире, который его уничтожает. Книга, написанная с болью и достоинством.', '/Мандельштам. Воспоминания. Шум времени.fb2', 'Воспоминания. Шум времени');
INSERT INTO public.books (id, description, file_path, title) VALUES (237, 'Сборник стихов Мандельштама — о любви, смерти и вечности. Автор создает поэзию, которая звучит как эпитафия и как гимн одновременно. Стихи, которые не стареют.', '/Мандельштам. За то, что я руки твои не сумел удержать.fb2', 'За то, что я руки твои не сумел удержать');
INSERT INTO public.books (id, description, file_path, title) VALUES (238, 'Роман о санатории, где время останавливается. Манн исследует, как болезнь обнажает суть человека — и как трудно найти смысл в мире, который движется к катастрофе. Книга, ставшая символом XX века.', '/Манн. Волшебная гора.fb2', 'Волшебная гора');
INSERT INTO public.books (id, description, file_path, title) VALUES (239, 'Роман о композиторе, который продает душу ради гениальности. Манн исследует, что важнее — искусство или человечность? Книга, написанная с философской глубиной и трагизмом.', '/Манн. Доктор Фаустус.fb2', 'Доктор Фаустус');
INSERT INTO public.books (id, description, file_path, title) VALUES (240, 'Роман о студенте, который ищет себя в мире, где все притворяются. Манн показывает, как легко потерять лицо — и как трудно найти свое призвание. Книга, написанная с психологической точностью.', '/Манн. Избранник.fb2', 'Избранник');
INSERT INTO public.books (id, description, file_path, title) VALUES (241, 'Философские размышления римского императора. Марк Аврелий учит: счастье — в контроле над собой, а не над миром. Книга, ставшая библией стоицизма.', '/Марк Аврелий. Наедине с собой.fb2', 'Наедине с собой');
INSERT INTO public.books (id, description, file_path, title) VALUES (242, 'Магический реализм о семье Буэндиа, чья судьба повторяется веками. Маркес создает мир, где реальность и фантазия неразделимы. Книга, ставшая символом латиноамериканской литературы.', '/Маркес. Сто лет одиночества (с илл.).fb2', 'Сто лет одиночества (с илл.)');
INSERT INTO public.books (id, description, file_path, title) VALUES (243, 'Новелла о преступлении, которое все знали, но не предотвратили. Маркес исследует, как общество создает жертву — и как трудно остановить неизбежное. Книга, написанная с драматизмом и иронией.', '/Маркес. Хроника объявленной смерти.fb2', 'Хроника объявленной смерти');
INSERT INTO public.books (id, description, file_path, title) VALUES (244, 'Манифест, написанный Энгельсом — краткое изложение идей, которые изменили мир. Маркс и Энгельс показывают, как капитализм порождает свою гибель. Книга, ставшая основой революций.', '/Маркс, Энгельс. Принципы коммунизма.fb2', 'Принципы коммунизма');
INSERT INTO public.books (id, description, file_path, title) VALUES (246, 'Анализ переворота, где Маркс показывает, как история повторяется — сначала как трагедия, потом как фарс. Книга, ставшая классикой политической теории.', '/Маркс. Восемнадцатое брюмера Луи Бонапарта.fb2', 'Восемнадцатое брюмера Луи Бонапарта');
INSERT INTO public.books (id, description, file_path, title) VALUES (247, 'Исследование одной из самых загадочных трагедий XX века. Матвеева показывает, как мифы рождаются из непонятного — и как трудно найти правду. Книга, написанная с уважением к погибшим.', '/Матвеева. Перевал Дятлова, или Тайна девяти.fb2', 'Перевал Дятлова, или Тайна девяти');
INSERT INTO public.books (id, description, file_path, title) VALUES (248, 'Поэма-манифест, где Маяковский кричит о революции, любви и поэзии. Автор создает стихи, которые звучат как призыв к бою — и как элегия одновременно. Поэзия, которая не стареет.', '/Маяковский. Во весь голос.fb2', 'Во весь голос');
INSERT INTO public.books (id, description, file_path, title) VALUES (249, 'Научно-популярная книга о том, как делать науку. Медавар показывает, что наука — это не гениальность, а труд, терпение и честность. Книга, написанная с юмором и мудростью.', '/Медавар. Советы молодому ученому.fb2', 'Советы молодому ученому');
INSERT INTO public.books (id, description, file_path, title) VALUES (250, 'Фантастика о девушке, которая борется с лунной принцессой. Мейер создает сказку будущего, где технологии и магия переплетаются. Книга, написанная с юмором и феминистским подтекстом.', '/Мейер. Лунные хроники. Красная шапочка.fb2', 'Лунные хроники. Красная шапочка');
INSERT INTO public.books (id, description, file_path, title) VALUES (251, 'Продолжение саги — о девушке с кибернетическими волосами. Мейер исследует, как технологии меняют личность — и как важно остаться человеком. Книга, написанная с фантазией и юмором.', '/Мейер. Лунные хроники. Рапунцель.fb2', 'Лунные хроники. Рапунцель');
INSERT INTO public.books (id, description, file_path, title) VALUES (252, 'Эпическая сага о капитане Ахаве, который охотится на кита — и на свою судьбу. Мелвилл создает аллегорию человеческого стремления — и его цены. Книга, ставшая символом американской литературы.', '/Мелвилл. Моби Дик, или Белый кит.fb2', 'Моби Дик, или Белый кит');
INSERT INTO public.books (id, description, file_path, title) VALUES (253, 'Биография основателя психоанализа. Мессер показывает, как гений формируется в борьбе с обществом — и как трудно остаться верным себе. Книга, написанная с уважением и критикой.', '/Мессер. Зигмунд Фрейд.fb2', 'Зигмунд Фрейд');
INSERT INTO public.books (id, description, file_path, title) VALUES (254, 'Научно-философские эссе о природе. Метерлинк показывает, как маленькие существа живут по законам, которые человек не понимает. Книга, написанная с поэтической точностью.', '/Метерлинк. Жизнь пчел. Разум цветов (сборник).fb2', 'Жизнь пчел. Разум цветов (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (255, 'Эпическая поэма о падении человека. Мильтон создает образ Сатаны, который стал символом бунта — и показывает, что свобода важнее рая. Книга, ставшая вершиной английской поэзии.', '/Мильтон. Потерянный рай.fb2', 'Потерянный рай');
INSERT INTO public.books (id, description, file_path, title) VALUES (256, 'Роман о поколении, которое живет для экрана. Минаев исследует, как технологии меняют личность — и как трудно остаться человеком в мире, где все — контент. Книга, написанная с сарказмом и болью.', '/Минаев. The Тёлки. Два года спустя, или Videotы.fb2', 'The Тёлки. Два года спустя, или Videotы');
INSERT INTO public.books (id, description, file_path, title) VALUES (257, 'Роман о жизни московских "тусовщиков". Минаев показывает, как гламур скрывает пустоту — и как трудно найти себя в мире, где все притворяются. Книга, ставшая символом 2000-х.', '/Минаев. The Телки.fb2', 'The Телки');
INSERT INTO public.books (id, description, file_path, title) VALUES (258, 'Продолжение истории о поколении, которое потеряло душу. Минаев исследует, как социальные сети создают иллюзию жизни — и как трудно вырваться из ловушки. Книга, написанная с цинизмом и надеждой.', '/Минаев. Дyxless 21 века. Селфи.fb2', 'Дyxless 21 века. Селфи');
INSERT INTO public.books (id, description, file_path, title) VALUES (259, 'Роман о поколении, которое живет без ценностей. Минаев показывает, как легко потерять себя в мире потребления — и как трудно найти смысл. Книга, ставшая культовой.', '/Минаев. Дyxless. Повесть о ненастоящем человеке.fb2', 'Дyxless. Повесть о ненастоящем человеке');
INSERT INTO public.books (id, description, file_path, title) VALUES (260, 'Биография певицы, которая стала символом эпохи. Мишаненкова показывает, как талант и характер создают легенду — и как трудно остаться человеком в мире славы. Книга, написанная с любовью и уважением.', '/Мишаненкова. Алла Пугачева.fb2', 'Алла Пугачева');
INSERT INTO public.books (id, description, file_path, title) VALUES (261, 'Биография дизайнера, которая изменила моду. Мишаненкова исследует, как амбиции и боль создают гения — и как трудно остаться женщиной в мире, который требует силы. Книга, написанная с элегантностью.', '/Мишаненкова. Коко Шанель.fb2', 'Коко Шанель');
INSERT INTO public.books (id, description, file_path, title) VALUES (262, 'Биография актрисы, которая стала символом советского кино. Мишаненкова показывает, как талант и обаяние покоряют мир — и как трудно сохранить личность в системе. Книга, написанная с ностальгией.', '/Мишаненкова. Любовь Орлова.fb2', 'Любовь Орлова');
INSERT INTO public.books (id, description, file_path, title) VALUES (263, 'Биография кинозвезды, которая стала иконой. Мишаненкова исследует, как слава разрушает личность — и как трудно остаться человеком в мире, где ты — товар. Книга, написанная с состраданием.', '/Мишаненкова. Мерилин Монро.fb2', 'Мерилин Монро');
INSERT INTO public.books (id, description, file_path, title) VALUES (264, 'Биография политика, который спас Британию. Мишаненкова показывает, как характер и воля формируют историю — и как трудно остаться человеком в мире войны. Книга, написанная с уважением.', '/Мишаненкова. Уинстон Черчилль.fb2', 'Уинстон Черчилль');
INSERT INTO public.books (id, description, file_path, title) VALUES (265, 'Биография литературного героя, который стал реальнее жизни. Мишаненкова исследует, как вымысел влияет на реальность — и как трудно отделить миф от правды. Книга, написанная с любовью к детективу.', '/Мишаненкова. Шерлок Холмс.fb2', 'Шерлок Холмс');
INSERT INTO public.books (id, description, file_path, title) VALUES (266, 'Роман о простом человеке, который ищет счастье. Мопассан показывает, как легко потерять себя в погоне за иллюзиями — и как трудно найти правду. Книга, написанная с реализмом и грустью.', '/Мопассан. Жизнь.fb2', 'Жизнь');
INSERT INTO public.books (id, description, file_path, title) VALUES (267, 'Роман о человеке, который теряет все — и находит себя. Мориак исследует, как страдание очищает душу — и как трудно принять милосердие. Книга, написанная с католической глубиной.', '/Мориак. Дорога в никуда.fb2', 'Дорога в никуда');
INSERT INTO public.books (id, description, file_path, title) VALUES (268, 'Роман в письмах о любви, которая длится всю жизнь — даже когда адресат не знает о ней. Моруа показывает, как страсть становится судьбой — и как трудно остаться незамеченным. Книга, написанная с лиризмом.', '/Моруа. Письма незнакомке.fb2', 'Письма незнакомке');
INSERT INTO public.books (id, description, file_path, title) VALUES (269, 'Роман о любовной интриге, которая длится годами. Моруа исследует, как страсть и расчет переплетаются в одном человеке. Книга, написанная с изяществом и иронией.', '/Моруа. Фиалки по средам.fb2', 'Фиалки по средам');
INSERT INTO public.books (id, description, file_path, title) VALUES (270, 'Роман о юноше, который ищет смысл жизни через любовь, искусство и страдание. Моэм показывает, что свобода — это не отсутствие оков, а принятие своей судьбы. Книга, ставшая автобиографией поколений.', '/Моэм. Бремя страстей человеческих.fb2', 'Бремя страстей человеческих');
INSERT INTO public.books (id, description, file_path, title) VALUES (271, 'Литературная критика, где Моэм анализирует классику. Автор показывает, что великая литература — это не стиль, а правда о человеке. Книга, написанная с умом и страстью.', '/Моэм. Десять величайших романов человечества.fb2', 'Десять величайших романов человечества');
INSERT INTO public.books (id, description, file_path, title) VALUES (272, 'Роман о художнике, который бросает все ради искусства. Моэм исследует, что важнее — комфорт или гений? Книга, вдохновленная жизнью Гогена.', '/Моэм. Луна и грош.fb2', 'Луна и грош');
INSERT INTO public.books (id, description, file_path, title) VALUES (273, 'Роман о писателе, который раскрывает тайны своих друзей. Моэм показывает, как легко разрушить репутацию — и как трудно остаться честным. Книга, написанная с сарказмом и мудростью.', '/Моэм. Пироги и пиво, или Скелет в шкафу.fb2', 'Пироги и пиво, или Скелет в шкафу');
INSERT INTO public.books (id, description, file_path, title) VALUES (274, 'Автобиографическая проза о жизни, литературе и смерти. Моэм исследует, как прожить жизнь без сожалений — и как трудно принять конец. Книга, написанная с честностью и спокойствием.', '/Моэм. Подводя итоги.fb2', 'Подводя итоги');
INSERT INTO public.books (id, description, file_path, title) VALUES (275, 'Трактат о стратегии, написанный самураем. Мусаси учит: победа — не в силе, а в понимании противника. Книга, ставшая библией воинов и бизнесменов.', '/Мусаси. Книга пяти колец.fb2', 'Книга пяти колец');
INSERT INTO public.books (id, description, file_path, title) VALUES (276, 'Дневник военного корреспондента — о самом страшном сражении XX века. Некрасов показывает, как человек выживает в аду — и как трудно остаться человеком. Книга, написанная с болью и правдой.', '/Некрасов. В окопах Сталинграда.fb2', 'В окопах Сталинграда');
INSERT INTO public.books (id, description, file_path, title) VALUES (277, 'Философские трактаты, где Ницше обличает христианство, восхваляет себя и разрушает идолы. Автор показывает, что истина — не в морали, а в воле к власти. Книга, ставшая манифестом бунта.', '/Ницше. Антихрист. Ecce Homo. Сумерки идолов (сборник).fb2', 'Антихрист. Ecce Homo. Сумерки идолов (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (278, 'Эссе о происхождении добра и зла. Ницше показывает, что мораль — это не истина, а инструмент власти. Книга, написанная с яростью и гениальностью.', '/Ницше. Генеалогия морали. Казус Вагнер.fb2', 'Генеалогия морали. Казус Вагнер');
INSERT INTO public.books (id, description, file_path, title) VALUES (279, 'Философская поэма о сверхчеловеке, который выходит за пределы добра и зла. Ницше создает манифест нового человека — свободного, сильного, творческого. Книга, ставшая библией XX века.', '/Ницше. Так говорил Заратустра.fb2', 'Так говорил Заратустра');
INSERT INTO public.books (id, description, file_path, title) VALUES (280, 'Роман о проповеднике, который отрицает Христа — и становится мучеником. О''Коннор исследует, как вера и отчаяние переплетаются в одном человеке. Книга, написанная с южным готическим ужасом.', '/О''Коннор. Мудрая кровь.fb2', 'Мудрая кровь');
INSERT INTO public.books (id, description, file_path, title) VALUES (281, 'Антивоенный роман о гибели поколения в Первой мировой. Олдингтон показывает, как война разрушает не только тела, но и души. Книга, написанная с болью и гневом.', '/Олдингтон. Смерть героя.fb2', 'Смерть героя');
INSERT INTO public.books (id, description, file_path, title) VALUES (282, 'Детская книга о девочке, которая находит семью. Олкотт создает мир, где любовь и доброта побеждают все. Книга, написанная с теплотой и юмором.', '/Олкотт. Роза Кэмпбелл 1. Роза и семь братьев.fb2', 'Роза Кэмпбелл 1. Роза и семь братьев');
INSERT INTO public.books (id, description, file_path, title) VALUES (283, 'Роман о музыканте, который продает душу дьяволу ради таланта. Орлов исследует, что важнее — гений или человечность? Книга, написанная с сарказмом и философской глубиной.', '/Орлов. Альтист Данилов.fb2', 'Альтист Данилов');
INSERT INTO public.books (id, description, file_path, title) VALUES (284, 'Эссе о том, как массовое общество уничтожает культуру. Ортега-и-Гассет показывает, что демократия — это не свобода, а тирания большинства. Книга, ставшая пророчеством XX века.', '/Ортега-и-Гассет. Восстание масс.fb2', 'Восстание масс');
INSERT INTO public.books (id, description, file_path, title) VALUES (285, 'Антиутопия о мире, где правда — это ложь, а свобода — рабство. Оруэлл создает образ тоталитарного государства, который остается актуальным. Книга, ставшая символом борьбы за правду.', '/Оруэлл. 1984.fb2', '1984');
INSERT INTO public.books (id, description, file_path, title) VALUES (286, 'Роман о колониальной Бирме — и внутреннем конфликте британского офицера. Оруэлл показывает, как империя разрушает и угнетателей, и угнетенных. Книга, написанная с честностью и болью.', '/Оруэлл. Глотнуть воздуха.fb2', 'Глотнуть воздуха');
INSERT INTO public.books (id, description, file_path, title) VALUES (287, 'Сборник эссе о политике, литературе и жизни. Оруэлл исследует, как язык формирует мышление — и как трудно остаться честным в мире лжи. Книга, написанная с ясностью и страстью.', '/Оруэлл. Да здравствует фикус!.fb2', 'Да здравствует фикус!');
INSERT INTO public.books (id, description, file_path, title) VALUES (288, 'Полуавтобиографический роман о службе в колониальной полиции. Оруэлл показывает, как империя унижает всех — и как трудно вырваться из системы. Книга, ставшая основой его мировоззрения.', '/Оруэлл. Дни в Бирме.fb2', 'Дни в Бирме');
INSERT INTO public.books (id, description, file_path, title) VALUES (289, 'Роман о девушке, которая ищет любовь — и находит предательство. Оруэлл исследует, как общество формирует судьбу — и как трудно остаться честным. Книга, написанная с реализмом и грустью.', '/Оруэлл. Дочь священника.fb2', 'Дочь священника');
INSERT INTO public.books (id, description, file_path, title) VALUES (290, 'Аллегория на сталинский режим, где животные устраивают революцию — и создают новую тиранию. Оруэлл показывает, что революция часто съедает своих детей. Книга, ставшая символом XX века.', '/Оруэлл. Скотный Двор. Эссе.fb2', 'Скотный Двор. Эссе');
INSERT INTO public.books (id, description, file_path, title) VALUES (291, 'Незавершенный роман о курортном городке. Остен создает сатиру на моду, сплетни и брак по расчету. Книга, написанная с иронией и любовью к человеческим слабостям.', '/Остен. Сэндитон.fb2', 'Сэндитон');
INSERT INTO public.books (id, description, file_path, title) VALUES (292, 'Комедия о девушке, которая играет в сваху — и попадает впросак. Остен показывает, как легко ошибиться в любви — и как трудно признать свою глупость. Книга, написанная с остроумием и теплотой.', '/Остен. Эмма.fb2', 'Эмма');
INSERT INTO public.books (id, description, file_path, title) VALUES (293, 'Роман-легенда о большевике, который побеждает боль и смерть. Островский создает образ нового человека — сильного, стойкого, преданного идеалу. Книга, ставшая символом советской эпохи.', '/Островский. Как закалялась сталь.fb2', 'Как закалялась сталь');
INSERT INTO public.books (id, description, file_path, title) VALUES (294, 'Религиозный текст о переходе души после смерти. Падмасамбхава учит: смерть — это не конец, а переход. Книга, ставшая мостом между культурами.', '/Падмасамбхава. Тибетская Книга мёртвых.fb2', 'Тибетская Книга мёртвых');
INSERT INTO public.books (id, description, file_path, title) VALUES (295, 'Роман о женщине, которая убивает своих детей — и находит покой. Паланик исследует, как отчаяние превращается в насилие — и как трудно вырваться из ловушки. Книга, написанная с шокирующей откровенностью.', '/Паланик. Колыбельная.fb2', 'Колыбельная');
INSERT INTO public.books (id, description, file_path, title) VALUES (296, 'Философские фрагменты о вере, разуме и человеке. Паскаль показывает, что сердце имеет свои разумы — и что человек — это трость, мыслящая трость. Книга, ставшая вершиной французской мысли.', '/Паскаль. Мысли.fb2', 'Мысли');
INSERT INTO public.books (id, description, file_path, title) VALUES (297, 'Сборник стихов Пастернака — о любви, природе и судьбе. Автор создает поэзию, которая звучит как молитва и как исповедь одновременно. Стихи, которые не стареют.', '/Пастернак. Во всем мне хочется дойти до самой сути.fb2', 'Во всем мне хочется дойти до самой сути');
INSERT INTO public.books (id, description, file_path, title) VALUES (298, 'Роман-эпопея о поэте, который теряет все в революции. Пастернак показывает, как история ломает судьбы — и как трудно остаться человеком. Книга, ставшая символом XX века.', '/Пастернак. Доктор Живаго.fb2', 'Доктор Живаго');
INSERT INTO public.books (id, description, file_path, title) VALUES (299, 'Роман о поколении, которое живет в мире рекламы. Пелевин исследует, как медиа создают реальность — и как трудно отличить иллюзию от правды. Книга, написанная с сарказмом и философской глубиной.', '/Пелевин. Generation «П».fb2', 'Generation «П»');
INSERT INTO public.books (id, description, file_path, title) VALUES (300, 'Роман о буддийском монахе, который ищет просветление — и находит любовь. Пелевин показывает, что истина — не в догмах, а в опыте. Книга, написанная с иронией и мудростью.', '/Пелевин. Искусство легких касаний.fb2', 'Искусство легких касаний');
INSERT INTO public.books (id, description, file_path, title) VALUES (301, 'Роман о человеке, который превращается в волка — и находит себя. Пелевин исследует, как маски становятся лицами — и как трудно остаться человеком. Книга, написанная с философской глубиной.', '/Пелевин. Священная книга оборотня.fb2', 'Священная книга оборотня');
INSERT INTO public.books (id, description, file_path, title) VALUES (302, 'Научно-популярная книга о математике в жизни. Перельман показывает, что числа — это не скучно, а увлекательно. Книга, написанная с юмором и любовью к науке.', '/Перельман. Живая математика (2021).fb2', 'Живая математика (2021)');
INSERT INTO public.books (id, description, file_path, title) VALUES (303, 'Философская проза о путешествии, где техника встречается с метафизикой. Персинг исследует, что такое качество — и как найти гармонию в мире. Книга, ставшая культовой.', '/Персинг. Дзэн и искусство ухода за мотоциклом.fb2', 'Дзэн и искусство ухода за мотоциклом');
INSERT INTO public.books (id, description, file_path, title) VALUES (304, 'Исторический роман о художнике, который рисует Страшный суд — и видит будущее. Перуц показывает, как искусство предсказывает судьбу — и как трудно остаться в живых, зная правду. Книга, написанная с готическим ужасом.', '/Перуц. Мастер Страшного суда.fb2', 'Мастер Страшного суда');
INSERT INTO public.books (id, description, file_path, title) VALUES (305, 'Диалог о справедливом обществе. Платон исследует, как устроить идеальное государство — и почему оно невозможно. Книга, ставшая основой политической философии.', '/Платон. Государство.fb2', 'Государство');
