INSERT INTO public.books (id, description, file_path, title) VALUES (307, 'Последний труд Платона — о реальном, а не идеальном государстве. Автор исследует, как законы формируют общество — и как трудно создать справедливость. Книга, написанная с мудростью и реализмом.', '/Платон. Законы.fb2', 'Законы');
INSERT INTO public.books (id, description, file_path, title) VALUES (308, 'Практическое руководство по логике и чтению. Поварнин учит: чтобы понять книгу, нужно спорить с ней. Книга, написанная с ясностью и пользой.', '/Поварнин. Искусство спора. Как читать книги.fb2', 'Искусство спора. Как читать книги');
INSERT INTO public.books (id, description, file_path, title) VALUES (309, 'Мемуары телеведущего — о советской и постсоветской эпохе. Познер показывает, как иллюзии разрушаются — и как трудно остаться честным. Книга, написанная с болью и надеждой.', '/Познер. Прощание с иллюзиями. «Поедемте в Англию».fb2', 'Прощание с иллюзиями. «Поедемте в Англию»');
INSERT INTO public.books (id, description, file_path, title) VALUES (310, 'Автобиографическая проза о жизни в СССР и за рубежом. Познер исследует, как человек меняется в разных системах — и как трудно найти правду. Книга, написанная с честностью и болью.', '/Познер. Прощание с иллюзиями.fb2', 'Прощание с иллюзиями');
INSERT INTO public.books (id, description, file_path, title) VALUES (311, 'Роман о поколении, которое потеряло ориентиры. Прилепин исследует, как жить, когда нет будущего — и как найти себя в мире, который рушится. Книга, написанная с болью и надеждой.', '/Прилепин. Ботинки, полные горячей водкой.fb2', 'Ботинки, полные горячей водкой');
INSERT INTO public.books (id, description, file_path, title) VALUES (312, 'Роман о человеке, который ищет искупление — и находит себя. Прилепин показывает, как вина формирует судьбу — и как трудно остаться чистым в мире грязи. Книга, написанная с психологической глубиной.', '/Прилепин. Грех.fb2', 'Грех');
INSERT INTO public.books (id, description, file_path, title) VALUES (313, 'Роман о войне, где реальность и фантазия переплетаются. Прилепин исследует, как человек выживает в аду — и как трудно остаться человеком. Книга, написанная с болью и поэзией.', '/Прилепин. Черная обезьяна.fb2', 'Черная обезьяна');
