INSERT INTO public.books (id, description, file_path, title) VALUES (317, 'Повесть о страсти, которая ведет к гибели. Пушкин создает образ, который стал символом азарта и рока. Книга, написанная с драматизмом и психологизмом.', '/Пушкин. Пиковая дама.fb2', 'Пиковая дама');
INSERT INTO public.books (id, description, file_path, title) VALUES (318, 'Биография царя, который стал символом тирании. Радзинский показывает, как власть разрушает личность — и как трудно остаться человеком. Книга, написанная с драматизмом и болью.', '/Радзинский. Иван Грозный.fb2', 'Иван Грозный');
