INSERT INTO public.books (id, description, file_path, title) VALUES (324, 'Две повести о деревне, которую затопляют — и людях, которые не хотят уходить. Распутин показывает, как корни держат крепче, чем страх. Книга, написанная с любовью к родной земле.', '/Распутин. Прощание с Матерой. Пожар.fb2', 'Прощание с Матерой. Пожар');
