INSERT INTO public.books (id, description, file_path, title) VALUES (327, 'Роман о любви в концлагере. Ремарк показывает, как человек сохраняет человечность в аду — и как трудно выжить, не потеряв душу. Книга, написанная с состраданием и болью.', '/Ремарк. Возлюби ближнего своего.fb2', 'Возлюби ближнего своего');
INSERT INTO public.books (id, description, file_path, title) VALUES (328, 'Роман о женщине, которая ищет любовь — и находит предательство. Ремарк исследует, как война разрушает судьбы — и как трудно остаться честным. Книга, написанная с лиризмом и болью.', '/Ремарк. Гэм.fb2', 'Гэм');
