INSERT INTO public.books (id, description, file_path, title) VALUES (331, 'Роман о концлагере, где заключенные борются за жизнь. Ремарк показывает, что даже в аду есть искра надежды — и что она стоит дороже всего. Книга, написанная с болью и достоинством.', '/Ремарк. Искра жизни.fb2', 'Искра жизни');
