INSERT INTO public.books (id, description, file_path, title) VALUES (333, 'Роман о беженцах, которые ищут спасения — и находят любовь. Ремарк исследует, как человек выживает в изгнании — и как трудно остаться человеком. Книга, написанная с болью и надеждой.', '/Ремарк. Ночь в Лиссабоне.fb2', 'Ночь в Лиссабоне');
