INSERT INTO public.books (id, description, file_path, title) VALUES (336, 'Роман о беженце, который ищет любовь — и находит смерть. Ремарк показывает, как легко потерять себя в чужой стране — и как трудно остаться человеком. Книга, написанная с болью и надеждой.', '/Ремарк. Триумфальная арка.fb2', 'Триумфальная арка');
INSERT INTO public.books (id, description, file_path, title) VALUES (337, 'Мистическое эссе о поиске духовного центра мира. Рерих исследует, как человек встречается с тайной — и как трудно найти истину. Книга, написанная с поэтической глубиной.', '/Рерих. Шамбала.fb2', 'Шамбала');
INSERT INTO public.books (id, description, file_path, title) VALUES (338, 'Фундаментальный труд, заложивший основы экономической теории. Рикардо показывает, как труд создает стоимость — и как налоги влияют на общество. Книга, изменившая экономику.', '/Рикардо. Начала политической экономии и налогового обложения.fb2', 'Начала политической экономии и налогового обложения');
INSERT INTO public.books (id, description, file_path, title) VALUES (339, 'Философские письма о творчестве, любви и одиночестве. Рильке учит: чтобы писать, нужно жить — и чтобы жить, нужно быть одиноким. Книга, ставшая библией для творческих людей.', '/Рильке. Письма к молодому поэту.fb2', 'Письма к молодому поэту');
INSERT INTO public.books (id, description, file_path, title) VALUES (340, 'Сборник поэзии Рождественского — о войне, любви и России. Автор создает стихи, которые звучат как песни и как молитвы одновременно. Поэзия, которая не стареет.', '/Рождественский. Лучшие стихи.fb2', 'Лучшие стихи');
INSERT INTO public.books (id, description, file_path, title) VALUES (341, 'Научно-популярная книга о людях с необычным восприятием. Сакс показывает, что "нормальность" — это иллюзия, а гений часто рождается из отклонения. Книга, написанная с состраданием и уважением.', '/Сакс. Антрополог на Марсе.fb2', 'Антрополог на Марсе');
INSERT INTO public.books (id, description, file_path, title) VALUES (342, 'Исследование о том, как мозг создает реальность. Сакс показывает, что галлюцинации — не безумие, а окно в работу сознания. Книга, написанная с научной точностью и поэзией.', '/Сакс. Галлюцинации.fb2', 'Галлюцинации');
INSERT INTO public.books (id, description, file_path, title) VALUES (343, 'Книга о том, как музыка влияет на мозг. Сакс исследует, почему мелодия может исцелять, вдохновлять и разрушать. Книга, написанная с любовью к науке и искусству.', '/Сакс. Музыкофилия.fb2', 'Музыкофилия');
INSERT INTO public.books (id, description, file_path, title) VALUES (344, 'Сборник клинических историй о неврологических расстройствах. Сакс показывает, что человек — это не диагноз, а личность. Книга, ставшая классикой нейропсихологии.', '/Сакс. Человек, который принял жену за шляпу.fb2', 'Человек, который принял жену за шляпу');
INSERT INTO public.books (id, description, file_path, title) VALUES (345, 'Автобиографическая повесть о детстве в советской семье. Санаев показывает, как любовь и боль переплетаются в одном доме — и как трудно вырасти, когда тебя не понимают. Книга, написанная с болью и юмором.', '/Санаев. Похороните меня за плинтусом.fb2', 'Похороните меня за плинтусом');
INSERT INTO public.books (id, description, file_path, title) VALUES (346, 'Роман о поколении, которое живет без ценностей. Санаев исследует, как легко потерять себя в мире потребления — и как трудно найти смысл. Книга, написанная с сарказмом и болью.', '/Санаев. Хроники раздолбая.fb2', 'Хроники раздолбая');
INSERT INTO public.books (id, description, file_path, title) VALUES (347, 'Пьеса о человеке, который теряет все — и находит себя. Сартр исследует, как свобода становится бременем — и как трудно остаться человеком. Книга, написанная с экзистенциальной глубиной.', '/Сартр. Ставок больше нет.fb2', 'Ставок больше нет');
INSERT INTO public.books (id, description, file_path, title) VALUES (348, 'Роман-исповедь о человеке, который чувствует тошноту от бытия. Сартр показывает, что существование предшествует сущности — и что человек обречен на свободу. Книга, ставшая манифестом экзистенциализма.', '/Сартр. Тошнота.fb2', 'Тошнота');
INSERT INTO public.books (id, description, file_path, title) VALUES (349, 'Роман о любви, которая длится всю жизнь — даже когда пути расходятся. Сафарли показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс. Книга, написанная с лиризмом.', '/Сафарли. Если бы ты знал.fb2', 'Если бы ты знал');
INSERT INTO public.books (id, description, file_path, title) VALUES (350, 'Роман о любви, которая начинается с письма. Сафарли исследует, как слова создают реальность — и как трудно остаться верным себе. Книга, написанная с нежностью и болью.', '/Сафарли. Мне тебя обещали.fb2', 'Мне тебя обещали');
INSERT INTO public.books (id, description, file_path, title) VALUES (351, 'Роман о книге, которая меняет судьбу. Сафон создает мир, где литература — это магия, а читатель — герой. Книга, написанная с любовью к книгам.', '/Сафон. Кладбище забытых книг 1. Тень ветра.fb2', 'Кладбище забытых книг 1. Тень ветра');
INSERT INTO public.books (id, description, file_path, title) VALUES (352, 'Продолжение саги — о писателе, который продает душу ради славы. Сафон исследует, что важнее — искусство или человечность? Книга, написанная с готическим ужасом.', '/Сафон. Кладбище забытых книг 2. Игра ангела.fb2', 'Кладбище забытых книг 2. Игра ангела');
INSERT INTO public.books (id, description, file_path, title) VALUES (353, 'Роман о тюрьме, где заключенные пишут книги. Сафон показывает, что свобода — не в стенах, а в словах. Книга, написанная с любовью к литературе.', '/Сафон. Кладбище забытых книг 3. Узники неба.fb2', 'Кладбище забытых книг 3. Узники неба');
INSERT INTO public.books (id, description, file_path, title) VALUES (354, 'Финал саги — о тайнах, которые связывают всех героев. Сафон создает эпическую историю, где каждая книга — это жизнь. Книга, написанная с мастерством и страстью.', '/Сафон. Кладбище забытых книг 4. Лабиринт призраков.fb2', 'Кладбище забытых книг 4. Лабиринт призраков');
INSERT INTO public.books (id, description, file_path, title) VALUES (355, 'Древнерусская поэма о походе князя Игоря. Автор создает эпический образ Руси — с болью, любовью и надеждой. Книга, ставшая символом русской литературы.', '/Сборник. Слово о полку Игореве.fb2', 'Слово о полку Игореве');
INSERT INTO public.books (id, description, file_path, title) VALUES (356, 'Биография основателя Apple. Секачева показывает, как гений и тирания создают революцию — и как трудно остаться человеком в мире технологий. Книга, написанная с уважением и критикой.', '/Секачева. Стив Джобс.fb2', 'Стив Джобс');
INSERT INTO public.books (id, description, file_path, title) VALUES (357, 'Философские письма о жизни, смерти и добродетели. Сенека учит: чтобы жить, нужно учиться умирать. Книга, ставшая библией стоицизма.', '/Сенека. Нравственные письма к Луцилию.fb2', 'Нравственные письма к Луцилию');
INSERT INTO public.books (id, description, file_path, title) VALUES (358, 'Эссе о том, как прожить жизнь, а не существовать. Сенека показывает, что время — это не деньги, а единственное, что у нас есть. Книга, написанная с мудростью и болью.', '/Сенека. О скоротечности жизни.fb2', 'О скоротечности жизни');
INSERT INTO public.books (id, description, file_path, title) VALUES (359, 'Роман о почтовых пилотах, которые летают в темноте. Сент-Экзюпери исследует, как человек встречается с бездной — и как трудно остаться живым. Книга, написанная с поэтической силой.', '/Сент-Экзюпери. Ночной полёт.fb2', 'Ночной полёт');
INSERT INTO public.books (id, description, file_path, title) VALUES (360, 'Научная фантастика о паломничестве к загадочной планете. Симмонс создает эпическую сагу, где мифология, философия и наука переплетаются. Книга, написанная с мастерством и страстью.', '/Симмонс. Гиперион.fb2', 'Гиперион');
INSERT INTO public.books (id, description, file_path, title) VALUES (361, 'Философский труд о том, что мораль основана на сочувствии. Смит показывает, что человек — не эгоист, а существо, способное к состраданию. Книга, заложившая основы экономической этики.', '/Смит. Теория нравственных чувств.fb2', 'Теория нравственных чувств');
INSERT INTO public.books (id, description, file_path, title) VALUES (362, 'Философская проза о природе любви. Соловьев исследует, как эрос и агапе переплетаются в одном чувстве. Книга, написанная с мистической глубиной.', '/Соловьев. Смысл любви.fb2', 'Смысл любви');
INSERT INTO public.books (id, description, file_path, title) VALUES (363, 'Роман о мире, где реальность и фантазия переплетаются. Сорокин создает сюрреалистическую картину России — с юмором, ужасом и болью. Книга, написанная с дерзостью и гениальностью.', '/Сорокин. Голубое сало.fb2', 'Голубое сало');
INSERT INTO public.books (id, description, file_path, title) VALUES (364, 'Антиутопия о будущей России, где царит средневековый порядок. Сорокин показывает, как легко вернуться в прошлое — и как трудно остаться человеком. Книга, написанная с сарказмом и ужасом.', '/Сорокин. День опричника.fb2', 'День опричника');
INSERT INTO public.books (id, description, file_path, title) VALUES (365, 'Роман о мире, где снег скрывает все — даже правду. Сорокин исследует, как человек выживает в хаосе — и как трудно найти смысл. Книга, написанная с атмосферой апокалипсиса.', '/Сорокин. Метель.fb2', 'Метель');
INSERT INTO public.books (id, description, file_path, title) VALUES (366, 'Роман о любви, которая длится всю жизнь — даже когда пути расходятся. Спаркс показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс. Книга, написанная с лиризмом.', '/Спаркс. Лучшее во мне.fb2', 'Лучшее во мне');
INSERT INTO public.books (id, description, file_path, title) VALUES (367, 'Философский трактат о том, как государство подавляет личность. Спенсер показывает, что свобода — это не хаос, а естественное состояние. Книга, ставшая основой либертарианства.', '/Спенсер. Личность и государство.fb2', 'Личность и государство');
INSERT INTO public.books (id, description, file_path, title) VALUES (368, 'Роман о женщине, которая выживает в концлагере — и теряет все. Стайрон показывает, как человек сохраняет человечность в аду — и как трудно остаться живым. Книга, написанная с болью и достоинством.', '/Стайрон. Выбор Софи.fb2', 'Выбор Софи');
INSERT INTO public.books (id, description, file_path, title) VALUES (369, 'Книга о театральной системе Станиславского. Автор учит: чтобы играть правду, нужно верить в нее. Книга, ставшая библией актеров.', '/Станиславский. Не верю!.fb2', 'Не верю!');
INSERT INTO public.books (id, description, file_path, title) VALUES (370, 'Практическое руководство по актерскому мастерству. Станиславский показывает, как создать живой образ — через внутреннюю работу. Книга, изменившая театр.', '/Станиславский. Работа актера над собой.fb2', 'Работа актера над собой');
INSERT INTO public.books (id, description, file_path, title) VALUES (371, 'Научная фантастика о контакте с инопланетной цивилизацией. Старджон показывает, что "человечность" — это не вид, а качество. Книга, написанная с философской глубиной.', '/Старджон. Больше чем люди.fb2', 'Больше чем люди');
INSERT INTO public.books (id, description, file_path, title) VALUES (372, 'Сборник рассказов о жизни в Калифорнии. Стейнбек показывает, как люди выживают в мире, который против них — и как трудно остаться честным. Книга, написанная с состраданием и болью.', '/Стейнбек. Долгая долина.fb2', 'Долгая долина');
INSERT INTO public.books (id, description, file_path, title) VALUES (373, 'Рассказ о группе людей, которые теряются в пустыне — и находят себя. Стейнбек исследует, как человек реагирует на кризис — и как трудно остаться человеком. Книга, написанная с психологической глубиной.', '/Стейнбек. Заблудившийся автобус.fb2', 'Заблудившийся автобус');
INSERT INTO public.books (id, description, file_path, title) VALUES (374, 'Роман о поколении, которое потеряло будущее. Стейнбек показывает, как легко прожить жизнь в долг — и как трудно заплатить по счетам. Книга, написанная с меланхолией и надеждой.', '/Стейнбек. Зима тревоги нашей (пер. Калашниковой, Волжиной).fb2', 'Зима тревоги нашей (пер. Калашниковой, Волжиной)');
INSERT INTO public.books (id, description, file_path, title) VALUES (375, 'Альтернативный перевод — с другой стилистикой, но той же болью. Стейнбек исследует, как человек живет, зная, что теряет все. Книга, написанная с болью и красотой.', '/Стейнбек. Зима тревоги нашей (пер. Целовальниковой).fb2', 'Зима тревоги нашей (пер. Целовальниковой)');
INSERT INTO public.books (id, description, file_path, title) VALUES (376, 'Эпическая сага о семье, где добро и зло борются в каждом. Стейнбек показывает, что человек сам выбирает свою судьбу — и что свобода — это бремя. Книга, ставшая символом американской литературы.', '/Стейнбек. К востоку от Эдема.fb2', 'К востоку от Эдема');
INSERT INTO public.books (id, description, file_path, title) VALUES (377, 'Две повести о жизни в Калифорнии. Стейнбек создает галерею чудаков, которые живут по своим законам. Книга, написанная с юмором и состраданием.', '/Стейнбек. Квартал Тортилья-Флэт. Консервный ряд.fb2', 'Квартал Тортилья-Флэт. Консервный ряд');
INSERT INTO public.books (id, description, file_path, title) VALUES (378, 'Две повести о мечте, которая разрушается. Стейнбек показывает, как легко потерять все — и как трудно остаться человеком. Книга, написанная с болью и надеждой.', '/Стейнбек. О мышах и людях. Жемчужина.fb2', 'О мышах и людях. Жемчужина');
INSERT INTO public.books (id, description, file_path, title) VALUES (379, 'Путевые заметки о стране, которая меняется. Стейнбек исследует, что значит быть американцем — и как трудно найти правду. Книга, написанная с любовью и болью.', '/Стейнбек. Путешествие с Чарли в поисках Америки.fb2', 'Путешествие с Чарли в поисках Америки');
INSERT INTO public.books (id, description, file_path, title) VALUES (380, 'Повесть о поэте, который ищет приют — и находит себя. Стивенсон показывает, как легко потерять себя в мире — и как трудно найти дом. Книга, написанная с лиризмом.', '/Стивенсон. Ночлег Франсуа Вийона.fb2', 'Ночлег Франсуа Вийона');
INSERT INTO public.books (id, description, file_path, title) VALUES (381, 'Роман о человеке, который разделяет себя на добро и зло. Стивенсон исследует, что значит быть человеком — и как трудно контролировать свою природу. Книга, ставшая символом двойственности.', '/Стивенсон. Странная история доктора Джекила и мистера Хайда.fb2', 'Странная история доктора Джекила и мистера Хайда');
INSERT INTO public.books (id, description, file_path, title) VALUES (382, 'Готический роман о древнем египетском проклятии. Стокер создает атмосферу ужаса, где прошлое мстит настоящему. Книга, написанная с мастерством и напряжением.', '/Стокер. Сокровище семи звезд.fb2', 'Сокровище семи звезд');
INSERT INTO public.books (id, description, file_path, title) VALUES (383, 'Биографический роман о Винсенте Ван Гоге. Стоун показывает, как гений рождается из боли — и как трудно остаться человеком. Книга, написанная с любовью и болью.', '/Стоун. Жажда жизни.fb2', 'Жажда жизни');
INSERT INTO public.books (id, description, file_path, title) VALUES (384, 'Философская проза о природе музыки. Стравинский исследует, как звук становится искусством — и как трудно объяснить гениальность. Книга, написанная с мудростью и страстью.', '/Стравинский. Музыкальная поэтика. В шести лекциях.fb2', 'Музыкальная поэтика. В шести лекциях');
INSERT INTO public.books (id, description, file_path, title) VALUES (385, 'Книга о методе актерской игры. Страсберг показывает, как создать правду на сцене — через внутреннюю боль. Книга, ставшая основой метода актерского мастерства.', '/Страсберг. Страстная мечта, или Сочиненные чувства.fb2', 'Страстная мечта, или Сочиненные чувства');
INSERT INTO public.books (id, description, file_path, title) VALUES (386, 'Научная фантастика о мире, где дети становятся иными. Стругацкие исследуют, как общество реагирует на "других" — и как трудно принять перемены. Книга, написанная с философской глубиной.', '/Стругацкие. Гадкие лебеди.fb2', 'Гадкие лебеди');
INSERT INTO public.books (id, description, file_path, title) VALUES (387, 'Фантастика о контакте с инопланетной цивилизацией. Стругацкие показывают, как легко разрушить чужую культуру — и как трудно понять "другого". Книга, написанная с напряжением и философией.', '/Стругацкие. Парень из преисподней.fb2', 'Парень из преисподней');
INSERT INTO public.books (id, description, file_path, title) VALUES (388, 'Научная фантастика о зоне, где физика нарушена. Стругацкие исследуют, как человек встречается с неизвестным — и как трудно остаться живым. Книга, ставшая основой фильма "Сталкер".', '/Стругацкие. Пикник на обочине.fb2', 'Пикник на обочине');
INSERT INTO public.books (id, description, file_path, title) VALUES (389, 'Две повести о космических путешествиях. Стругацкие показывают, как наука встречается с моралью — и как трудно остаться человеком. Книга, написанная с юмором и философией.', '/Стругацкие. Путь на Амальтею. Стажеры.fb2', 'Путь на Амальтею. Стажеры');
INSERT INTO public.books (id, description, file_path, title) VALUES (390, 'Сатира на советскую бюрократию. Стругацкие создают мир, где абсурд — единственный способ выжить. Книга, написанная с остроумием и гневом.', '/Стругацкие. Сказка о Тройке.fb2', 'Сказка о Тройке');
INSERT INTO public.books (id, description, file_path, title) VALUES (391, 'Историческое исследование о начале Первой мировой войны. Такман показывает, как ошибки, гордыня и случайности приводят к катастрофе. Книга, ставшая классикой военной истории.', '/Такман. Августовские пушки.fb2', 'Августовские пушки');
INSERT INTO public.books (id, description, file_path, title) VALUES (392, 'Поэма о солдате, который проходит войну с юмором и стойкостью. Твардовский создает образ, который стал символом русского солдата. Стихи, которые не стареют.', '/Твардовский. Василий Теркин.fb2', 'Василий Теркин');
INSERT INTO public.books (id, description, file_path, title) VALUES (393, 'Роман о двух подругах, которые ищут счастья в высшем обществе. Теккерей показывает, как легко потерять себя в погоне за славой — и как трудно остаться честным. Книга, написанная с сарказмом и мудростью.', '/Теккерей. Ярмарка тщеславия.fb2', 'Ярмарка тщеславия');
INSERT INTO public.books (id, description, file_path, title) VALUES (394, 'Антиутопия о мире, где язык разрушается, а люди теряют себя. Толстая исследует, как культура формирует личность — и как трудно остаться человеком. Книга, написанная с философской глубиной.', '/Толстая. Кысь.fb2', 'Кысь');
INSERT INTO public.books (id, description, file_path, title) VALUES (395, 'Готическая повесть о вампирах, которые любят своих жертв. Толстой А. создает атмосферу ужаса, где любовь и смерть переплетаются. Книга, написанная с мастерством и жутью.', '/Толстой А. Семья вурдалака.fb2', 'Семья вурдалака');
INSERT INTO public.books (id, description, file_path, title) VALUES (396, 'Сборник рассказов о любви, которая разрушает. Толстой Л. исследует, как страсть ведет к гибели — и как трудно остаться чистым. Книга, написанная с психологической глубиной.', '/Толстой Л. Без любви жить легче.fb2', 'Без любви жить легче');
INSERT INTO public.books (id, description, file_path, title) VALUES (397, 'Эпическая сага о России в эпоху Наполеона. Толстой показывает, как история формирует судьбы — и как трудно остаться человеком. Книга, ставшая символом мировой литературы.', '/Толстой Л. Война и мир. Книга 1.fb2', 'Война и мир. Книга 1');
INSERT INTO public.books (id, description, file_path, title) VALUES (398, 'Продолжение — о войне, любви и поиске смысла. Толстой исследует, что значит быть человеком в мире, который движется к катастрофе. Книга, написанная с эпическим размахом.', '/Толстой Л. Война и мир. Книга 2.fb2', 'Война и мир. Книга 2');
INSERT INTO public.books (id, description, file_path, title) VALUES (399, 'Автобиографическая трилогия о становлении личности. Толстой показывает, как человек ищет себя в мире, который требует масок. Книга, написанная с психологической глубиной.', '/Толстой Л. Детство. Отрочество. Юность.fb2', 'Детство. Отрочество. Юность');
INSERT INTO public.books (id, description, file_path, title) VALUES (400, 'Сборник рассказов о грехе, искушении и совести. Толстой исследует, как легко потерять себя — и как трудно найти правду. Книга, написанная с болью и мудростью.', '/Толстой Л. Дьявол (сборник).fb2', 'Дьявол (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (401, 'Философская проза о природе страдания и освобождения. Торчинов показывает, что буддизм — это не религия, а путь к просветлению. Книга, написанная с ясностью и глубиной.', '/Торчинов. Введение в буддизм.fb2', 'Введение в буддизм');
INSERT INTO public.books (id, description, file_path, title) VALUES (402, 'Сатира на советскую действительность. Тул создает мир, где абсурд — единственный способ выжить. Книга, написанная с остроумием и гневом.', '/Тул. Сговор остолопов.fb2', 'Сговор остолопов');
INSERT INTO public.books (id, description, file_path, title) VALUES (403, 'Два романа о любви, которая длится всю жизнь — даже когда пути расходятся. Тургенев показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс. Книга, написанная с лиризмом.', '/Тургенев. Вешние воды. Накануне (сборник).fb2', 'Вешние воды. Накануне (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (404, 'Сборник стихов Тютчева — о любви, природе и судьбе. Автор создает поэзию, которая звучит как молитва и как исповедь одновременно. Стихи, которые не стареют.', '/Тютчев. О, как убийственно мы любим.fb2', 'О, как убийственно мы любим');
INSERT INTO public.books (id, description, file_path, title) VALUES (405, 'Мемуары о медицине в СССР. Углов показывает, как наука выживает в мире, который ее не ценит. Книга, написанная с болью и достоинством.', '/Углов. Воспоминание русского хирурга.fb2', 'Воспоминание русского хирурга');
INSERT INTO public.books (id, description, file_path, title) VALUES (406, 'Пьеса о женщине, которая теряет все — и находит себя. Уильямс исследует, как легко разрушить иллюзию — и как трудно остаться человеком. Книга, написанная с драматизмом и болью.', '/Уильямс. Трамвай «Желание» (сборник).fb2', 'Трамвай «Желание» (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (407, 'Научная фантастика о мире, где растения захватывают планету. Уиндем показывает, как легко потерять контроль — и как трудно выжить. Книга, написанная с напряжением и философией.', '/Уиндем. Во всем виноват лишайник.fb2', 'Во всем виноват лишайник');
INSERT INTO public.books (id, description, file_path, title) VALUES (408, 'Роман о мире, где слепые люди борются с плотоядными растениями. Уиндем исследует, как человек выживает в апокалипсисе — и как трудно остаться человеком. Книга, ставшая классикой фантастики.', '/Уиндем. День триффидов.fb2', 'День триффидов');
