INSERT INTO public.books (id, description, file_path, title) VALUES (411, 'Роман о мире, где дети рождаются другими. Уиндем показывает, как общество реагирует на "других" — и как трудно принять перемены. Книга, написанная с философской глубиной.', '/Уиндем. Куколки.fb2', 'Куколки');
