INSERT INTO public.books (id, description, file_path, title) VALUES (419, 'Сборник стихов Фета — о любви, природе и вечности. Автор создает поэзию, которая звучит как музыка и как молитва одновременно. Стихи, которые не стареют.', '/Фет. Я пришел к тебе с приветом….fb2', 'Я пришел к тебе с приветом…');
