INSERT INTO public.books (id, description, file_path, title) VALUES (441, 'Утопия о мире, где счастье — это гармония. Хаксли показывает, что рай возможен — если человек готов к нему. Книга, написанная с мудростью и болью.', '/Хаксли. Остров.fb2', 'Остров');
INSERT INTO public.books (id, description, file_path, title) VALUES (442, 'Роман о человеке, который теряет зрение — и находит себя. Хаксли исследует, как легко потерять себя — и как трудно найти правду. Книга, написанная с психологической глубиной.', '/Хаксли. Слепец в Газе.fb2', 'Слепец в Газе');
INSERT INTO public.books (id, description, file_path, title) VALUES (443, 'Роман о поколении, которое потеряло будущее. Хаксли показывает, как легко прожить жизнь в долг — и как трудно заплатить по счетам. Книга, написанная с меланхолией и надеждой.', '/Хаксли. Эти опавшие листья.fb2', 'Эти опавшие листья');
INSERT INTO public.books (id, description, file_path, title) VALUES (444, 'Роман о женщине, которая живет своей жизнью — вопреки всему. Хандке исследует, как найти счастье в маленьких радостях — и как важно не сдаваться. Книга, написанная с теплотой и мудростью.', '/Хандке. Женщина-левша.fb2', 'Женщина-левша');
INSERT INTO public.books (id, description, file_path, title) VALUES (445, 'Эссе о красоте математики. Харди показывает, что наука — это не польза, а искусство. Книга, написанная с любовью и страстью.', '/Харди. Апология математика.fb2', 'Апология математика');
INSERT INTO public.books (id, description, file_path, title) VALUES (446, 'Роман о кризисе в аэропорту. Хейли показывает, как человек реагирует на стресс — и как трудно остаться честным. Книга, написанная с напряжением и драматизмом.', '/Хейли. Аэропорт.fb2', 'Аэропорт');
INSERT INTO public.books (id, description, file_path, title) VALUES (447, 'Роман о расследовании убийства. Хейли исследует, как легко ошибиться в поисках правды — и как трудно остаться человеком. Книга, написанная с мастерством и напряжением.', '/Хейли. Детектив.fb2', 'Детектив');
INSERT INTO public.books (id, description, file_path, title) VALUES (448, 'Роман о жизни в отеле — и судьбах, которые переплетаются. Хейли показывает, как легко потерять себя в мире, который движется к катастрофе. Книга, написанная с драматизмом и болью.', '/Хейли. Отель.fb2', 'Отель');
INSERT INTO public.books (id, description, file_path, title) VALUES (449, 'Роман о человеке, который теряет все — и находит себя. Хемингуэй исследует, как легко разрушить жизнь — и как трудно остаться человеком. Книга, написанная с болью и достоинством.', '/Хемингуэй. Иметь и не иметь.fb2', 'Иметь и не иметь');
INSERT INTO public.books (id, description, file_path, title) VALUES (450, 'Роман о войне, где любовь и смерть переплетаются. Хемингуэй показывает, как человек выживает в аду — и как трудно остаться человеком. Книга, ставшая символом XX века.', '/Хемингуэй. По ком звонит колокол.fb2', 'По ком звонит колокол');
INSERT INTO public.books (id, description, file_path, title) VALUES (451, 'Роман о любви, которая длится всю жизнь — даже когда пути расходятся. Хемингуэй показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс. Книга, написанная с лиризмом.', '/Хемингуэй. Райский сад.fb2', 'Райский сад');
INSERT INTO public.books (id, description, file_path, title) VALUES (452, 'Две повести о борьбе человека с природой. Хемингуэй показывает, что победа — не в результате, а в борьбе. Книга, написанная с мужеством и простотой.', '/Хемингуэй. Старик и море. Зеленые холмы Африки.fb2', 'Старик и море. Зеленые холмы Африки');
INSERT INTO public.books (id, description, file_path, title) VALUES (453, 'Приключенческий роман о поисках редкого животного. Хоук создает мир, где приключения — это путь к себе. Книга, написанная с юмором и азартом.', '/Хоук. В поисках тигра.fb2', 'В поисках тигра');
INSERT INTO public.books (id, description, file_path, title) VALUES (454, 'Продолжение — о борьбе с природой и собой. Хоук показывает, как легко потерять себя в мире, который против тебя. Книга, написанная с драматизмом и болью.', '/Хоук. Проклятие тигра.fb2', 'Проклятие тигра');
INSERT INTO public.books (id, description, file_path, title) VALUES (455, 'Биография королевы, которая стала символом роскоши и падения. Цвейг показывает, как легко потерять трон — и как трудно остаться человеком. Книга, написанная с элегантностью и болью.', '/Цвейг. Мария Антуанетта. Портрет ординарного характера.fb2', 'Мария Антуанетта. Портрет ординарного характера');
INSERT INTO public.books (id, description, file_path, title) VALUES (456, 'Сборник стихов Цветаевой — о любви, боли и поиске себя. Автор создает поэзию, которая звучит как крик и как молитва одновременно. Стихи, которые не стареют.', '/Цветаева. Живу до тошноты.fb2', 'Живу до тошноты');
INSERT INTO public.books (id, description, file_path, title) VALUES (457, 'Сборник стихов Цветаевой — о детстве, любви и тоске. Автор исследует, как легко потерять себя — и как трудно найти правду. Книга, написанная с болью и нежностью.', '/Цветаева. Под лаской плюшевого пледа.fb2', 'Под лаской плюшевого пледа');
INSERT INTO public.books (id, description, file_path, title) VALUES (458, 'Сборник стихов Цветаевой — о любви, смерти и вечности. Автор создает поэзию, которая звучит как эпитафия и как гимн одновременно. Стихи, которые не стареют.', '/Цветаева. Хочу у зеркала, где муть.fb2', 'Хочу у зеркала, где муть');
INSERT INTO public.books (id, description, file_path, title) VALUES (459, 'Исторический труд о завоевании Галлии. Цезарь показывает, как человек формирует историю — и как трудно остаться честным. Книга, ставшая классикой военной истории.', '/Цезарь Гай Юлий. Записки о Галльской войне.fb2', 'Записки о Галльской войне');
INSERT INTO public.books (id, description, file_path, title) VALUES (460, 'Философский трактат о пути и добродетели. Цзы показывает, что истина — не в словах, а в бездействии. Книга, ставшая основой даосизма.', '/Цзы. Дао дэ Цзин.fb2', 'Дао дэ Цзин');
INSERT INTO public.books (id, description, file_path, title) VALUES (461, 'Философские размышления о страдании. Цицерон учит: чтобы жить, нужно учиться умирать. Книга, ставшая библией стоицизма.', '/Цицерон. О боли, горе и смерти.fb2', 'О боли, горе и смерти');
INSERT INTO public.books (id, description, file_path, title) VALUES (462, 'Биографии святых и эссе о вере. Честертон показывает, что ортодоксия — это не догма, а приключение. Книга, написанная с юмором и страстью.', '/Честертон. Фома. Франциск. Ортодоксия.fb2', 'Фома. Франциск. Ортодоксия');
INSERT INTO public.books (id, description, file_path, title) VALUES (463, 'Мемуары великого певца. Шаляпин показывает, как талант и характер создают легенду — и как трудно остаться человеком в мире славы. Книга, написанная с любовью и болью.', '/Шаляпин. Я был отчаянно провинциален….fb2', 'Я был отчаянно провинциален…');
INSERT INTO public.books (id, description, file_path, title) VALUES (464, 'Две трагедии о власти, любви и падении. Шекспир показывает, как легко потерять трон — и как трудно остаться человеком. Книга, ставшая символом мировой литературы.', '/Шекспир. Король Лир. Антоний и Клеопатра (сборник).fb2', 'Король Лир. Антоний и Клеопатра (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (465, 'Две трагедии о любви, которая ведет к гибели. Шекспир исследует, как страсть разрушает все — даже того, кто ее испытывает. Книга, написанная с драматизмом и психологизмом.', '/Шекспир. Ромео и Джульетта. Отелло.fb2', 'Ромео и Джульетта. Отелло');
INSERT INTO public.books (id, description, file_path, title) VALUES (466, 'Роман о женщине, которая теряет все — и находит себя. Шелдон показывает, как легко разрушить жизнь — и как трудно остаться человеком. Книга, написанная с драматизмом и болью.', '/Шелдон. Если наступит завтра.fb2', 'Если наступит завтра');
INSERT INTO public.books (id, description, file_path, title) VALUES (467, 'Роман о ученом, который создает жизнь — и теряет себя. Шелли исследует, что значит быть человеком — и как трудно контролировать свою природу. Книга, ставшая символом фантастики.', '/Шелли. Франкенштейн, или Современный Прометей.fb2', 'Франкенштейн, или Современный Прометей');
INSERT INTO public.books (id, description, file_path, title) VALUES (468, 'Биография актера, который стал символом эпохи. Шляхов показывает, как талант и обаяние покоряют мир — и как трудно сохранить личность в системе. Книга, написанная с ностальгией.', '/Шляхов. Андрей Миронов.fb2', 'Андрей Миронов');
INSERT INTO public.books (id, description, file_path, title) VALUES (469, 'Две повести о войне, где реальность и фантазия переплетаются. Шолохов показывает, как человек выживает в аду — и как трудно остаться человеком. Книга, написанная с болью и поэзией.', '/Шолохов. Судьба человека. Донские рассказы.fb2', 'Судьба человека. Донские рассказы');
INSERT INTO public.books (id, description, file_path, title) VALUES (470, 'Сборник мыслей о жизни, смерти и человеческой природе. Шопенгауэр показывает, что счастье — это отсутствие страдания. Книга, написанная с мудростью и цинизмом.', '/Шопенгауэр. Афоризмы житейской мудрости.fb2', 'Афоризмы житейской мудрости');
INSERT INTO public.books (id, description, file_path, title) VALUES (471, 'Практическое руководство по логике и риторике. Шопенгауэр учит: чтобы победить в споре, нужно знать слабости противника. Книга, написанная с ясностью и пользой.', '/Шопенгауэр. Искусство побеждать в спорах. Мысли.fb2', 'Искусство побеждать в спорах. Мысли');
INSERT INTO public.books (id, description, file_path, title) VALUES (472, 'Философский труд о природе реальности. Шопенгауэр показывает, что мир — это воля, а счастье — в отказе от нее. Книга, изменившая философию.', '/Шопенгауэр. Мир как воля и представление.fb2', 'Мир как воля и представление');
INSERT INTO public.books (id, description, file_path, title) VALUES (473, 'Пьеса о неравенстве и справедливости. Шоу показывает, как легко потерять себя в мире, который требует масок. Книга, написанная с сарказмом и мудростью.', '/Шоу. Богач, бедняк.fb2', 'Богач, бедняк');
INSERT INTO public.books (id, description, file_path, title) VALUES (474, 'Пьеса о власти, любви и падении. Шоу исследует, как легко потерять трон — и как трудно остаться человеком. Книга, написанная с драматизмом и болью.', '/Шоу. Вершина холма.fb2', 'Вершина холма');
INSERT INTO public.books (id, description, file_path, title) VALUES (475, 'Пьеса о любви, которая длится всю жизнь — даже когда пути расходятся. Шоу показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс. Книга, написанная с лиризмом.', '/Шоу. Вечер в Византии.fb2', 'Вечер в Византии');
INSERT INTO public.books (id, description, file_path, title) VALUES (476, 'Пьеса о войне, где реальность и фантазия переплетаются. Шоу показывает, как человек выживает в аду — и как трудно остаться человеком. Книга, написанная с болью и поэзией.', '/Шоу. Допустимые потери.fb2', 'Допустимые потери');
INSERT INTO public.books (id, description, file_path, title) VALUES (477, 'Пьеса о женщине, которая ищет любовь — и находит предательство. Шоу исследует, как легко потерять себя — и как трудно найти правду. Книга, написанная с психологической глубиной.', '/Шоу. Люси Краун.fb2', 'Люси Краун');
INSERT INTO public.books (id, description, file_path, title) VALUES (478, 'Пьеса о бедности и справедливости. Шоу показывает, как легко потерять себя в мире, который против тебя. Книга, написанная с сарказмом и болью.', '/Шоу. Нищий, вор.fb2', 'Нищий, вор');
INSERT INTO public.books (id, description, file_path, title) VALUES (479, 'Пьеса о человеке, который теряет все — и находит себя. Шоу исследует, как легко разрушить жизнь — и как трудно остаться человеком. Книга, написанная с драматизмом и болью.', '/Шоу. Ночной портье.fb2', 'Ночной портье');
INSERT INTO public.books (id, description, file_path, title) VALUES (480, 'Пьеса о любви, которая длится всю жизнь — даже когда пути расходятся. Шоу показывает, как судьба возвращает людей друг к другу — и как важно не упустить второй шанс. Книга, написанная с лиризмом.', '/Шоу. Ошибка мертвого жокея.fb2', 'Ошибка мертвого жокея');
INSERT INTO public.books (id, description, file_path, title) VALUES (481, 'Пьеса о профессоре, который создает леди из цветочницы. Шоу исследует, как легко потерять себя — и как трудно найти правду. Книга, ставшая основой мюзикла "Моя прекрасная леди".', '/Шоу. Пигмалион.fb2', 'Пигмалион');
INSERT INTO public.books (id, description, file_path, title) VALUES (482, 'Пьеса о мире, где реальность и фантазия переплетаются. Шоу показывает, как человек выживает в аду — и как трудно остаться человеком. Книга, написанная с болью и поэзией.', '/Шоу. Солнечные берега реки Леты.fb2', 'Солнечные берега реки Леты');
INSERT INTO public.books (id, description, file_path, title) VALUES (483, 'Пьеса о власти, любви и падении. Шоу исследует, как легко потерять трон — и как трудно остаться человеком. Книга, написанная с драматизмом и болью.', '/Шоу. Цезарь и Клеопатра (сборник).fb2', 'Цезарь и Клеопатра (сборник)');
INSERT INTO public.books (id, description, file_path, title) VALUES (484, 'Научно-философская проза о природе жизни. Шредингер показывает, что жизнь — это не химия, а информация. Книга, изменившая биологию.', '/Шредингер. Что такое жизнь.fb2', 'Что такое жизнь');
INSERT INTO public.books (id, description, file_path, title) VALUES (485, 'Детектив в средневековом монастыре. Эко создает мир, где книги — это оружие, а знание — опасно. Книга, ставшая символом интеллектуального триллера.', '/Эко. Имя розы (с илл.).fb2', 'Имя розы (с илл.)');
INSERT INTO public.books (id, description, file_path, title) VALUES (486, 'Исторический труд о том, как общество формирует институты. Энгельс показывает, что все начинается с экономики. Книга, изменившая социологию.', '/Энгельс. Происхождение семьи, частной собственности и государства.fb2', 'Происхождение семьи, частной собственности и государства');
INSERT INTO public.books (id, description, file_path, title) VALUES (487, 'Философские диалоги о природе свободы и добродетели. Эпиктет учит: чтобы быть свободным, нужно контролировать только себя. Книга, ставшая библией стоицизма.', '/Эпиктет. Беседы.fb2', 'Беседы');
INSERT INTO public.books (id, description, file_path, title) VALUES (488, 'Философский труд о природе разума, эмоций и морали. Юм показывает, что все знание — из опыта. Книга, изменившая философию.', '/Юм. Трактат о человеческой природе.fb2', 'Трактат о человеческой природе');
INSERT INTO public.books (id, description, file_path, title) VALUES (489, 'Психологический труд о глубинных структурах психики. Юнг показывает, что мифы — это не вымысел, а отражение души. Книга, изменившая психологию.', '/Юнг. Архетипы и коллективное бессознательное.fb2', 'Архетипы и коллективное бессознательное');
INSERT INTO public.books (id, description, file_path, title) VALUES (490, 'Эссе о природе личности. Юнг исследует, как человек встречается с собой — и как трудно найти правду. Книга, написанная с мудростью и болью.', '/Юнг. Нераскрытая самость.fb2', 'Нераскрытая самость');
INSERT INTO public.books (id, description, file_path, title) VALUES (491, 'Лекции о природе бессознательного. Юнг показывает, что психоанализ — это не наука, а путь к себе. Книга, ставшая основой аналитической психологии.', '/Юнг. О психоанализе.fb2', 'О психоанализе');
INSERT INTO public.books (id, description, file_path, title) VALUES (492, 'Эссе о кризисе современного человека. Юнг исследует, как легко потерять себя — и как трудно найти правду. Книга, написанная с мудростью и болью.', '/Юнг. Проблемы души нашего времени (сборник).fb2', 'Проблемы души нашего времени (сборник)');
